async function chatScreen(){const requestedChat=Number(activeChat);$('#chatView')?.remove();app.insertAdjacentHTML('beforeend','<section class="chat-layout" id="chatView"><div class="empty" style="padding:24px">در حال دریافت پیام‌ها…</div></section>');let d;try{d=await api(`/chats/${requestedChat}/messages`)}catch(err){if(view!=='chat'||Number(activeChat)!==requestedChat)return;const box=$('#chatView');if(box)box.innerHTML=`<div class="empty" style="padding:24px">${esc(err.message)}<p><button class="btn" id="aceRetryChat">تلاش دوباره</button></p></div>`;$('#aceRetryChat')?.addEventListener('click',chatScreen);return}if(view!=='chat'||Number(activeChat)!==requestedChat)return;$('#chatView')?.remove();const peer=chatPeer||{display_name:'گفتگو'};app.insertAdjacentHTML('beforeend',`<section class="chat-layout" id="chatView"><header class="chat-head"><button class="iconbtn" id="backChats">‹</button>${avatar(peer)}<div class="grow"><b data-profile="${peer.id||peer.user_id||''}" class="${peer.equipped_name_color?'ace-name-'+peer.equipped_name_color:''}">${esc(peer.display_name)}</b><small class="muted" style="display:block" id="peerPresence">گفتگوی خصوصی · وضعیت در حال بررسی</small></div><button class="iconbtn voice-call-btn voice-call-disabled" id="voiceCall" title="تماس صوتی در بروزرسانی بعدی فعال می‌شود" aria-label="تماس صوتی؛ در بروزرسانی بعدی" disabled aria-disabled="true"><span aria-hidden="true">☎</span><small>به‌زودی</small></button><button class="ace-action-icon ace-menu-icon" id="chatMenu" aria-label="گزینه‌های گفتگو"><img src="/assets/ace-ui/menu-orbit.svg" alt=""></button></header><div class="messages" id="messages">${d.messages.map(messageHtml).join('')}</div><form class="chat-compose" id="compose"><label class="iconbtn" style="margin:0;cursor:pointer" title="ارسال عکس یا ویس">＋<input type="file" id="mediaFile" accept="image/*" hidden></label><textarea id="messageText" class="field" rows="1" placeholder="پیام بنویس…"></textarea><button class="iconbtn voice-coming-soon" type="button" id="recordBtn" title="ضبط ویس؛ به‌زودی" disabled aria-disabled="true"><span>🎙️</span><small>به‌زودی</small></button><button class="btn" type="submit">➤</button></form></section>`);$('#backChats').onclick=()=>goBack();$('#chatMenu').onclick=()=>showChatActions(activeChat,peer);$('#voiceCall').onclick=null;const presence=$('#peerPresence');if(presence){const seen=peer.last_seen?new Date(peer.last_seen+'Z').toLocaleString('fa-IR'):'نامشخص';presence.textContent=peer.online?'آنلاین':'آخرین بازدید: '+seen;}
const composer=$('#messageText');if(composer){composer.setAttribute('autocomplete','off');composer.setAttribute('enterkeyhint','send');composer.addEventListener('focus',()=>{aceChatWasTyping=true});composer.addEventListener('input',()=>{aceChatWasTyping=true});composer.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#compose')?.requestSubmit()}});if(aceChatWasTyping)setTimeout(()=>{if(view==='chat'&&activeChat&&document.visibilityState==='visible'){composer.focus({preventScroll:true});try{composer.setSelectionRange(composer.value.length,composer.value.length)}catch{}}},180)}
let replyTo=null;$('#compose').onsubmit=async e=>{e.preventDefault();const body=$('#messageText').value.trim();if(!body)return;try{await api(`/chats/${activeChat}/messages`,{method:'POST',body:{body,replyTo}});replyTo=null;$('#messageText').value='';aceChatWasTyping=true;loadMessages()}catch(err){toast(err.message)}};$('#mediaFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')){toast('ارسال ویس فعلاً غیرفعال است؛ به‌زودی');e.target.value='';return}const fd=new FormData();fd.append('file',f);try{await api(`/chats/${activeChat}/media`,{method:'POST',body:fd});loadMessages()}catch(err){toast(err.message)}};let recorder=null, chunks=[], activeStream=null, isStartingRecording=false;
$('#recordBtn').onclick=async()=>{
 const btn=$('#recordBtn');
 if(isStartingRecording)return;
 if(recorder?.state==='recording'){recorder.stop();btn.textContent='🎙';return}
 isStartingRecording=true;
 try{
  if(!navigator.mediaDevices?.getUserMedia)throw new Error('getUserMedia پشتیبانی نمی‌شود');
  if(typeof MediaRecorder==='undefined')throw new Error('MediaRecorder پشتیبانی نمی‌شود');
  if(activeStream?.getTracks().some(t=>t.readyState==='live')){activeStream.getTracks().forEach(t=>t.stop());activeStream=null}
  try{activeStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false})}
  catch(firstErr){if(firstErr?.name==='NotReadableError'||firstErr?.name==='AbortError'){await new Promise(resolve=>setTimeout(resolve,350));activeStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false})}else throw firstErr}
  const types=['audio/webm;codecs=opus','audio/webm','audio/mp4'];
  const mimeType=types.find(t=>{try{return MediaRecorder.isTypeSupported(t)}catch{return false}});
  recorder=mimeType?new MediaRecorder(activeStream,{mimeType}):new MediaRecorder(activeStream);
  chunks=[];
  recorder.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};
  recorder.onstop=async()=>{
   const finishedRecorder=recorder;
   try{
    const type=finishedRecorder?.mimeType||'audio/webm';
    const blob=new Blob(chunks,{type});
    if(!blob.size){toast('صدایی ضبط نشد');return}
    const fd=new FormData();
    fd.append('file',blob,'voice.'+(type.includes('mp4')?'mp4':'webm'));
    await api(`/chats/${activeChat}/media`,{method:'POST',body:fd});
    loadMessages();
   }catch(err){console.error('Voice upload error:',err);toast(err.message)}
   finally{
    activeStream?.getTracks().forEach(t=>t.stop());
    activeStream=null;recorder=null;chunks=[];
    btn.textContent='🎙';
    btn.disabled=false;
   }
  };
  recorder.start();
  btn.textContent='⏹';
 }catch(err){
  console.error('Voice recording error:',err);
  activeStream?.getTracks().forEach(t=>t.stop());
  activeStream=null;
  const friendly=err?.name==='NotReadableError'?'میکروفون توسط سیستم یا برنامهٔ دیگری قفل شده است. تماس‌ها و برنامه‌های ضبط صدا را ببند؛ اگر در اپ هستی مجوز Microphone را در تنظیمات اندروید بررسی و دوباره تلاش کن.':err?.name==='NotAllowedError'?'اجازهٔ میکروفون داده نشده؛ مجوز Microphone اپ و سایت را فعال کن.':err?.name==='OverconstrainedError'?'تنظیمات خاص میکروفون پشتیبانی نمی‌شود؛ دوباره تلاش کن.':err?.name==='SecurityError'?'ضبط صدا به اتصال امن HTTPS و مجوز میکروفون نیاز دارد.':(err?.message||'خطای نامشخص');
  toast('خطای ضبط: '+(err.name||'Error')+' - '+friendly);
 }finally{
  isStartingRecording=false;
 }
};
function loadMessages(){api(`/chats/${activeChat}/messages`).then(x=>{const el=$('#messages');if(el){el.innerHTML=x.messages.map(messageHtml).join('');el.scrollTop=el.scrollHeight}})}$('#messages').scrollTop=$('#messages').scrollHeight}
function messageHtml(m){if(m.deleted)return `<div class="bubble ${m.sender_id===me.id?'mine':''} muted">این پیام حذف شده</div>`;let body=esc(m.body);if(m.type==='sticker')body=`<span class="emoji-sticker">${esc(m.body)}</span>`;else if(m.type==='image'||m.type==='gif')body=`<img class="chat-image" src="${esc(m.media_url)}" alt="${m.type==='gif'?'GIF':'تصویر'}">`;if(m.type==='audio')body='<div class="voice-disabled-note"><span>🎙️</span><b>پیام صوتی</b><small>به‌زودی</small></div>';return `<div class="bubble message-glass tone-${Number(m.id)%3} ${m.sender_id===me.id?'mine':''}" data-message="${m.id}">${m.reply_to?`<div class="reply-reference">↪ پاسخ به پیام #${Number(m.reply_to)}</div>`:''}${body}<button class="message-reply-btn" data-message-reply="${m.id}" title="پاسخ">↩</button><time>${new Date(m.created_at+'Z').toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})} ${m.sender_id===me.id?`<span class="message-state" title="${m.read_at?'خوانده‌شده':m.delivered_at?'تحویل‌شده':'ارسال‌شده'}">${m.read_at?'✓✓':m.delivered_at?'✓✓':'✓'}</span>`:''}</time></div>`}
