async function wheelScreen(){shell(`${topbar('گردونه شانس')}<main class="content"><div class="card" style="text-align:center"><h2>🎡 گردونه شانس روزانه</h2><p class="muted">هر روز یک بار شانس خودت را امتحان کن.</p><div class="wheel" id="wheel"><span>ایس کلاب</span></div><button class="btn gold block" id="spin">چرخاندن گردونه</button><p class="muted small">جایزه به‌صورت تصادفی انتخاب می‌شود.</p></div></main>`);$('#spin').onclick=async()=>{const w=$('#wheel');$('#spin').disabled=true;w.style.transform=`rotate(${1440+Math.floor(Math.random()*720)}deg)`;try{const d=await api('/wheel',{method:'POST',body:{}});setTimeout(()=>{toast('🎉 جایزه شما: '+d.prize);me=d.user;render()},3500)}catch(e){setTimeout(()=>{toast(e.message);$('#spin').disabled=false},3500)}}}

async function promotedGroupsScreen(){const draw=async()=>{shell(`${topbar('گروه‌های ترویج‌شده')}<main class="content"><div class="hero"><h2>گروه‌های ترویج‌شده</h2><p>گروه‌هایی که برای نمایش در این بخش ترویج شده‌اند.</p></div><button class="btn secondary block" id="refreshPromotedGroups">↻ بروزرسانی گروه‌ها</button><div class="card" id="promotedGroupList"><div class="muted">در حال بارگذاری…</div></div></main>`);const box=$('#promotedGroupList');try{const d=await api('/groups/promoted');box.innerHTML=d.groups.map(g=>`<div class="userrow"><span class="group-avatar">${g.avatar?`<img src="${esc(g.avatar)}" alt="">`:'👥'}</span><span class="grow"><strong>${esc(g.name)}${g.owner_view?' <span class="pill">ترویج خودت</span>':''}</strong><small class="muted">@${esc(g.group_code)} · ${Number(g.member_count||0)} عضو · ✨ ${Number(g.fame||0)} شهرت${g.owner_view?` · ${Number(g.promoted_remaining||0).toLocaleString('fa-IR')} نمایش باقی‌مانده`:''}</small></span>${g.joined?`<button class="btn secondary" data-open-group="${g.id}">ورود</button>`:`<button class="btn secondary" data-promoted-request="${g.id}">عضویت در گروه</button>`}</div>`).join('')||'<div class="empty">فعلاً گروه ترویج‌شده‌ای وجود ندارد.</div>'}catch(err){box.innerHTML=`<div class="empty">بارگذاری گروه‌ها ناموفق بود: ${esc(err.message)}</div>`}$('#refreshPromotedGroups').onclick=draw};await draw()}
async function inviteGroupMemberScreen(id){
 const layer=document.createElement('div');layer.className='chat-action-overlay';
 layer.innerHTML=`<section class="chat-action-sheet group-members-sheet"><div class="sheet-handle"></div><h3>افزودن عضو به گروه</h3><p class="muted">فقط افرادی که دنبال کرده‌ای نمایش داده می‌شوند.</p><input class="field" id="groupMemberSearch" placeholder="جست‌وجو در دنبال‌شده‌ها…"><div id="groupMemberResults" class="card group-member-results"><div class="muted">در حال بارگذاری…</div></div><div id="groupMemberMore" class="muted small group-member-more"></div><button class="btn secondary block" data-sheet-close>بستن</button></section>`;
 document.body.append(layer);
 const box=$('#groupMemberResults'),more=$('#groupMemberMore'),search=$('#groupMemberSearch');
 let offset=0,loading=false,hasMore=true,currentQ='',timer=null;
 const sendInvite=async(userId,button)=>{
  try{
   await api(`/groups/${id}/invites`,{method:'POST',body:{userId:Number(userId)}});
   toast('دعوت گروه ارسال شد و اعلان برای کاربر ثبت شد');
   if(button){button.disabled=true;button.textContent='دعوت ارسال شد'}
  }catch(err){toast(err.message)}
 };
 const load=async(reset=false)=>{
  if(loading||(!hasMore&&!reset))return;
  if(reset){offset=0;hasMore=true;box.innerHTML='';more.textContent='در حال بارگذاری…'}
  loading=true;
  try{
   const d=await api(`/groups/${id}/invite-candidates?kind=following&offset=${offset}&limit=100&q=${encodeURIComponent(currentQ)}`);
   const users=d.users||[];
   const html=users.map(u=>`<div class="userrow">${avatar(u)}<span class="grow"><b>${esc(u.display_name||u.username)}</b><small class="muted">@${esc(u.username)} · کد ${Number(u.id)}</small></span><button class="btn secondary" data-invite-user="${u.id}">دعوت</button></div>`).join('');
   if(reset)box.innerHTML=html||'<div class="empty">کاربری پیدا نشد.</div>';else if(html)box.insertAdjacentHTML('beforeend',html);
   offset=d.nextOffset??offset;
   hasMore=!!d.hasMore;
   more.textContent=hasMore?'اسکرول کن تا افراد بیشتری نمایش داده شوند.':'به انتهای فهرست رسیدی.';
  }catch(err){
   if(reset)box.innerHTML=`<div class="empty">${esc(err.message)}</div>`;
   more.textContent='';
  }finally{loading=false}
 };
 layer.addEventListener('click',async e=>{
  if(e.target===layer||e.target.closest('[data-sheet-close]')){layer.remove();return}
  const b=e.target.closest('[data-invite-user]');
  if(b)await sendInvite(b.dataset.inviteUser,b);
 });
 box.addEventListener('scroll',()=>{if(box.scrollTop+box.clientHeight>=box.scrollHeight-160)load(false)});
 search.oninput=()=>{
  clearTimeout(timer);
  timer=setTimeout(()=>{currentQ=search.value.trim();load(true)},250);
 };
 await load(true);
}

async function followsScreen(kind){
 const following=kind==='following',title=following?'دنبال‌شونده‌ها':'دنبال‌کننده‌ها';
 const draw=async()=>{try{const d=await api('/follows/'+kind);shell(`${topbar(title)}<main class="content"><div class="card follows-list">${(d.users||[]).map(u=>`<div class="userrow follow-row">${avatar(u)}<button class="follow-user grow" data-public-profile="${u.id}"><b>${esc(u.display_name||u.username)}</b><small class="muted">@${esc(u.username||'')} · سطح ${Number(u.level||1)}</small></button>${following?`<button class="btn secondary unfollow-btn" data-unfollow="${u.id}" data-unfollow-name="${esc(u.display_name||u.username)}">دنبال‌شدن ✓</button>`:`<span class="muted small">دنبال‌کننده</span>`}</div>`).join('')||`<div class="empty">${following?'هنوز کسی را دنبال نکرده‌ای.':'هنوز دنبال‌کننده‌ای نداری.'}</div>`}</div></main>`)}catch(err){shell(`${topbar(title)}<main class="content"><div class="empty">${esc(err.message)}</div></main>`)}};
 await draw();
}

