async function notificationSettingsScreen(){const d=await api('/notification-settings');const labels=[['messages','پیام‌ها','اعلان پیام خصوصی و درخواست گفتگو'],['coins','سکه و الماس','تغییر موجودی، جایزه و تراکنش'],['profile_views','بازدید پروفایل','وقتی کسی از پروفایلت بازدید می‌کند'],['likes','لایک‌ها','لایک و واکنش به فعالیت‌ها'],['friends','دوستی و دنبال‌کردن','درخواست دنبال کردن و دنبال‌کننده جدید'],['games','بازی‌ها و شهرت','نتیجه مسابقه، شهرت و رتبه'],['support','پشتیبانی','پاسخ تیکت‌ها و وضعیت پشتیبانی'],['important','اعلان‌های مهم برنامه','اطلاعیه رسمی و اعلان سازنده'],['system','سایر اعلان‌ها','اعلان‌های عمومی دیگر']];let prefs=d.preferences||{};shell(`${topbar('تنظیمات اعلان')}<main class="content"><button class="btn secondary block" data-back>← بازگشت</button><div class="card"><h3>🔔 مدیریت اعلان‌ها</h3><p class="muted small">هر گزینه را جداگانه روشن یا خاموش کن. انتخاب‌ها در حساب کاربری ذخیره می‌شوند.</p>${labels.map(([key,title,desc])=>`<label class="notification-setting-row"><span><b>${title}</b><small class="muted">${desc}</small></span><input type="checkbox" data-notification-pref="${key}" ${prefs[key]!==false?'checked':''} aria-label="${title}"></label>`).join('')}<button class="btn block" id="saveNotificationPrefs" style="margin-top:14px">ذخیره تنظیمات</button></div></main>`);$('#saveNotificationPrefs').onclick=async()=>{const next={};document.querySelectorAll('[data-notification-pref]').forEach(el=>next[el.dataset.notificationPref]=el.checked);try{await api('/notification-settings',{method:'PUT',body:{preferences:next}});toast('تنظیمات اعلان ذخیره شد')}catch(err){toast(err.message)}}}
function themeSettingsScreen(){shell(`${topbar('۲۰ تم رنگی برنامه')}<main class="content"><div class="card"><p class="muted">تم دلخواه را انتخاب و ذخیره کن.</p><div class="theme-swatches">${themeOptions.map(t=>`<button type="button" class="theme-swatch" data-theme-pick="${t[0]}" style="--swatch:${t[2]}" title="${t[1]}"><i></i><small>${t[1]}</small></button>`).join('')}</div><label>انتخاب تم</label><select class="field" id="theme">${themeOptions.map(t=>`<option value="${t[0]}">${t[1]}</option>`).join('')}</select><button class="btn block" id="saveTheme" style="margin-top:12px">ذخیره و اعمال تم</button></div></main>`);$('#theme').value=localStorage.getItem('ddtheme')||'dark';document.querySelectorAll('[data-theme-pick]').forEach(b=>b.onclick=()=>{$('#theme').value=b.dataset.themePick;applyTheme(b.dataset.themePick)});$('#saveTheme').onclick=()=>{const t=$('#theme').value;localStorage.setItem('ddtheme',t);applyTheme(t);toast('تم ذخیره و اعمال شد')}}
function backgroundSettingsScreen(){shell(`${topbar('پس‌زمینه چت‌ها')}<main class="content"><div class="card"><p class="muted">پس‌زمینه فقط روی گفت‌وگوهای خصوصی و گروهی اعمال می‌شود.</p><label>۲۰ پس‌زمینه آماده چت</label><select class="field" id="backgroundPreset">${backgroundOptions.map(b=>`<option value="${b[0]}">${b[1]}</option>`).join('')}</select><button class="btn secondary block" id="applyBackground" style="margin-top:10px">اعمال پس‌زمینه چت</button><div class="divider"></div><label>انتخاب عکس از گالری گوشی</label><input class="field" type="file" id="backgroundFile" accept="image/*"><button class="btn block" id="applyBackgroundFile" style="margin-top:10px">اعمال عکس برای چت‌ها</button><button class="btn secondary block" id="resetBackground" style="margin-top:10px">بازگشت چت‌ها به پیش‌فرض</button><p class="muted small">عکس تا ۳ مگابایت روی همین دستگاه ذخیره می‌شود.</p></div></main>`);$('#backgroundPreset').value=localStorage.getItem('ddchatbackground')||'default';$('#applyBackground').onclick=()=>{const bg=$('#backgroundPreset').value;localStorage.setItem('ddchatbackground',bg);localStorage.removeItem('ddchatbackgroundImage');applyChatBackground(bg);toast('پس‌زمینه چت‌ها اعمال شد')};$('#applyBackgroundFile').onclick=()=>{const file=$('#backgroundFile').files[0];if(!file)return toast('اول یک عکس انتخاب کن');if(!file.type.startsWith('image/'))return toast('فایل باید عکس باشد');if(file.size>3*1024*1024)return toast('حجم عکس باید کمتر از ۳ مگابایت باشد');const reader=new FileReader();reader.onload=()=>{try{localStorage.setItem('ddchatbackgroundImage',reader.result);localStorage.setItem('ddchatbackground','custom');applyChatBackground('custom');toast('عکس گالری روی چت‌ها اعمال شد')}catch{toast('ذخیره عکس ممکن نشد؛ عکس کم‌حجم‌تری انتخاب کن')}};reader.readAsDataURL(file)};$('#resetBackground').onclick=()=>{localStorage.removeItem('ddchatbackgroundImage');localStorage.setItem('ddchatbackground','default');applyChatBackground('default');toast('پس‌زمینه چت‌ها پیش‌فرض شد')}}
function appBackgroundSettingsScreen(){shell(`${topbar('پس‌زمینه برنامه')}<main class="content"><div class="card"><p class="muted">این تنظیم فقط پس‌زمینه صفحه‌های برنامه را تغییر می‌دهد و پس‌زمینه چت را دست‌نخورده می‌گذارد.</p><label>پس‌زمینه آماده</label><select class="field" id="appBackgroundPreset">${backgroundOptions.map(b=>`<option value="${b[0]}">${b[1]}</option>`).join('')}</select><button class="btn secondary block" id="applyAppBackground" style="margin-top:10px">اعمال پس‌زمینه برنامه</button><div class="divider"></div><label>یا عکس از گالری گوشی</label><input class="field" type="file" id="appBackgroundFile" accept="image/*"><button class="btn block" id="applyAppBackgroundFile" style="margin-top:10px">استفاده از عکس برای برنامه</button><button class="btn secondary block" id="resetAppBackground" style="margin-top:10px">بازگشت برنامه به پیش‌فرض</button><p class="muted small">عکس تا ۳ مگابایت و فقط روی همین دستگاه ذخیره می‌شود.</p></div></main>`);$('#appBackgroundPreset').value=localStorage.getItem('ddappbackground')||'default';$('#applyAppBackground').onclick=()=>{const bg=$('#appBackgroundPreset').value;localStorage.setItem('ddappbackground',bg);localStorage.removeItem('ddappbackgroundImage');applyAppBackground(bg);toast('پس‌زمینه برنامه اعمال شد')};$('#applyAppBackgroundFile').onclick=()=>{const file=$('#appBackgroundFile').files[0];if(!file)return toast('اول یک عکس انتخاب کن');if(!file.type.startsWith('image/'))return toast('فایل باید عکس باشد');if(file.size>3*1024*1024)return toast('حجم عکس باید کمتر از ۳ مگابایت باشد');const reader=new FileReader();reader.onload=()=>{try{localStorage.setItem('ddappbackgroundImage',reader.result);localStorage.setItem('ddappbackground','custom');applyAppBackground('custom');toast('عکس روی پس‌زمینه برنامه اعمال شد')}catch{toast('ذخیره عکس ممکن نشد؛ عکس کم‌حجم‌تری انتخاب کن')}};reader.readAsDataURL(file)};$('#resetAppBackground').onclick=()=>{localStorage.removeItem('ddappbackgroundImage');localStorage.setItem('ddappbackground','default');applyAppBackground('default');toast('پس‌زمینه برنامه پیش‌فرض شد')}}
function wallpaperPresets(){return {default:'none',aurora:'radial-gradient(ellipse at 15% 0%,#075985 0,transparent 42%),radial-gradient(ellipse at 90% 35%,#4c1d95 0,transparent 42%)',midnight:'radial-gradient(ellipse at 50% 0%,#263449 0,transparent 65%)',ember:'radial-gradient(ellipse at 100% 0%,#7f1d1d 0,transparent 55%)',ocean:'radial-gradient(ellipse at 0% 0%,#064e3b 0,transparent 55%),radial-gradient(ellipse at 100% 100%,#0c4a6e 0,transparent 55%)',forest:'radial-gradient(ellipse at 80% 0%,#14532d 0,transparent 55%)',nebula:'radial-gradient(ellipse at 20% 0%,#581c87 0,transparent 50%),radial-gradient(ellipse at 90% 80%,#1e3a8a 0,transparent 50%)',rose:'radial-gradient(ellipse at 80% 0%,#881337 0,transparent 55%)',sapphire:'radial-gradient(ellipse at 20% 20%,#1d4ed8,transparent 60%)',amethyst:'radial-gradient(ellipse at 80% 10%,#7e22ce,transparent 60%)',golden:'radial-gradient(ellipse at 80% 10%,#854d0e,transparent 55%)',silver:'radial-gradient(ellipse at 20% 10%,#64748b,transparent 60%)',ice:'radial-gradient(ellipse at 20% 0%,#155e75,transparent 55%)',lavender:'radial-gradient(ellipse at 80% 0%,#6d28d9,transparent 55%)',cherry:'radial-gradient(ellipse at 80% 0%,#9f1239,transparent 55%)',desert:'radial-gradient(ellipse at 70% 0%,#92400e,transparent 55%)',rain:'radial-gradient(ellipse at 10% 0%,#334155,transparent 60%)',galaxy:'radial-gradient(ellipse at 10% 0%,#581c87,transparent 50%),radial-gradient(ellipse at 90% 80%,#1e40af,transparent 50%)',carbon:'radial-gradient(ellipse at 50% 0%,#374151,transparent 60%)',mint:'radial-gradient(ellipse at 70% 0%,#065f46,transparent 55%)'}}
function applyAppBackground(bg){const img=localStorage.getItem('ddappbackgroundImage');const preset=wallpaperPresets()[bg]||'none';document.body.style.backgroundImage=bg==='custom'&&img?`linear-gradient(rgba(7,8,12,.24),rgba(7,8,12,.38)),url("${img}")`:preset;document.body.style.backgroundSize='cover';document.body.style.backgroundAttachment='fixed';document.body.style.backgroundPosition='center'}
function applyChatBackground(bg){const img=localStorage.getItem('ddchatbackgroundImage');const preset=wallpaperPresets()[bg]||'none';const value=bg==='custom'&&img?`linear-gradient(rgba(7,8,12,.24),rgba(7,8,12,.38)),url("${img}")`:preset;document.documentElement.style.setProperty('--chat-wallpaper',value)}


function applyTheme(t){const colors={dark:'#08a9e7',blue:'#3989ff',purple:'#c026d3',red:'#ef4444',green:'#10b981',gold:'#f59e0b',pink:'#ec4899',cyan:'#06b6d4',orange:'#f97316',indigo:'#6366f1',rose:'#fb7185',teal:'#14b8a6',lime:'#84cc16',violet:'#8b5cf6',ice:'#7dd3fc',ruby:'#e11d48',mint:'#34d399',copper:'#c2410c',ocean:'#0284c7',lavender:'#a78bfa'};document.documentElement.style.setProperty('--blue',colors[t]||colors.dark)}
async function editProfileScreen(){shell(`${topbar('ویرایش پروفایل')}<main class="content"><form id="profileEdit" class="card edit-profile-card"><div class="edit-profile-avatar">${avatar(me,'large')}<label class="btn secondary" for="avatarFile">📷 انتخاب عکس از گوشی</label><input class="field" type="file" id="avatarFile" accept="image/*" hidden></div><label>نام نمایشی</label><input class="field" name="display_name" maxlength="40" required value="${esc(me.display_name)}"><label>درباره من</label><textarea class="field" name="bio" maxlength="300" rows="4" placeholder="چند خط درباره خودت…">${esc(me.bio||'')}</textarea><label>شهر / استان</label><input class="field" name="province" maxlength="80" value="${esc(me.province||'')}" placeholder="مثلاً تهران"><label>شماره تلفن</label><input class="field readonly-field" value="${esc(me.phone||'ثبت نشده')}" readonly><label>شناسه کاربری</label><input class="field readonly-field" value="${Number(me.id)}" readonly><button class="btn block" style="margin-top:18px" type="submit">ذخیره تغییرات</button></form></main>`);$('#profileEdit').onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target);const data={display_name:fd.get('display_name'),bio:fd.get('bio'),province:fd.get('province')};const d=await api('/profile',{method:'PATCH',body:data});me=d.user;const file=$('#avatarFile').files[0];if(file){const upload=new FormData();upload.append('file',file);const a=await api('/profile/avatar',{method:'POST',body:upload});me=a.user}toast('تغییرات پروفایل ذخیره شد');view='profile';viewStack=[];profileScreen()}catch(err){toast(err.message)}};const avatarInput=$('#avatarFile');if(avatarInput)avatarInput.onchange=()=>{const file=avatarInput.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('لطفاً فایل تصویری انتخاب کن');avatarInput.value='';return}const reader=new FileReader();reader.onload=()=>{const box=$('.edit-profile-avatar .avatar');if(box)box.innerHTML=`<img src="${reader.result}" alt="پیش‌نمایش عکس">`};reader.readAsDataURL(file)}}
function openAvatarViewer(src,name){if(!src)return toast('برای این کاربر عکسی ثبت نشده');const overlay=document.createElement('div');overlay.className='avatar-viewer';overlay.innerHTML=`<button class="avatar-viewer-close" aria-label="بستن">×</button><img src="${esc(src)}" alt="${esc(name||'عکس پروفایل')}"><div>${esc(name||'عکس پروفایل')}</div>`;overlay.addEventListener('click',()=>overlay.remove());document.body.append(overlay)}
function showInfoSheet(title,body){const layer=document.createElement('div');layer.className='chat-action-overlay';layer.innerHTML=`<section class="chat-action-sheet"><div class="sheet-handle"></div><h3>${esc(title)}</h3><p class="muted" style="white-space:pre-line;line-height:1.9">${esc(body)}</p><button data-sheet-close>باشه</button></section>`;layer.onclick=e=>{if(e.target===layer||e.target.closest('[data-sheet-close]'))layer.remove()};document.body.append(layer)}

function showOwnProfileMenu(){const old=$('.chat-action-overlay');old?.remove();const layer=document.createElement('div');layer.className='chat-action-overlay';layer.innerHTML=`<section class="chat-action-sheet"><div class="sheet-handle"></div><h3>گزینه‌های پروفایل</h3><button data-own-profile-option="editProfile">✏️ ویرایش پروفایل</button><button data-own-profile-option="blocked">🚫 کاربران مسدودشده</button><button data-own-profile-option="settings">⚙ تنظیمات</button><button data-own-profile-option="security">🛡️ امنیت حساب</button><button data-own-profile-option="transactions">🧾 تراکنش‌ها</button><button data-own-profile-option="support">🎧 پشتیبانی</button><button data-own-profile-option="logout" class="sheet-danger">↪ خروج از حساب</button><button data-sheet-close>بستن</button></section>`;layer.addEventListener('click',e=>{if(e.target===layer||e.target.closest('[data-sheet-close]')){layer.remove();return}const b=e.target.closest('[data-own-profile-option]');if(!b)return;layer.remove();if(b.dataset.ownProfileOption==='editProfile')go('editProfile');else if(b.dataset.ownProfileOption==='blocked')go('blockedUsers');else if(b.dataset.ownProfileOption==='settings')go('settings');else if(b.dataset.ownProfileOption==='transactions')go('transactions');else if(b.dataset.ownProfileOption==='support')go('tickets');else if(b.dataset.ownProfileOption==='logout'){api('/auth/logout',{method:'POST'}).then(()=>{me=null;view='home';viewStack=[];if(socket){socket.disconnect();socket=null}render()}).catch(err=>toast(err.message))}else go('security')});document.body.append(layer)}

function showPublicProfileActions(id){const layer=document.createElement('div');layer.className='chat-action-overlay';layer.innerHTML=`<section class="chat-action-sheet"><div class="sheet-handle"></div><h3>گزینه‌های پروفایل</h3><button data-p-action="message">✉ درخواست پیام · ۱۰ سکه</button><button data-p-action="friend">♧ درخواست دنبال کردن</button><button data-p-action="like">♡ لایک</button><button data-p-action="report">⚑ گزارش پروفایل</button><button data-p-action="block" class="sheet-danger">${window.currentPublicProfile?.id===Number(id)&&window.currentPublicProfile?.blocked?'🔓 رفع مسدودی کاربر':'🚫 مسدودسازی کاربر'}</button><button data-sheet-close>بستن</button></section>`;layer.addEventListener('click',async e=>{if(e.target===layer||e.target.closest('[data-sheet-close]')){layer.remove();return}const b=e.target.closest('[data-p-action]');if(!b)return;try{if(b.dataset.pAction==='message')await api(`/users/${id}/message-request`,{method:'POST',body:{}});else if(b.dataset.pAction==='friend')await api(`/users/${id}/friend-request`,{method:'POST',body:{}});else if(b.dataset.pAction==='like')await api(`/users/${id}/like`,{method:'POST'});else if(b.dataset.pAction==='report'){const reason=await acePrompt('علت گزارش پروفایل؟');if(!reason?.trim())return;await api('/reports',{method:'POST',body:{category:'profile',targetType:'profile',targetId:String(id),reportedUserId:id,reason:reason.trim()}})}else if(b.dataset.pAction==='block'){const isBlocked=window.currentPublicProfile?.id===Number(id)&&window.currentPublicProfile?.blocked;if(!await aceConfirm(isBlocked?'مسدودی این کاربر برداشته شود؟':'ارتباط پیام‌رسانی با این کاربر بسته شود؟ این محدودیت در سمت سرور اعمال می‌شود.'))return;if(isBlocked){await api(`/users/${id}/block`,{method:'DELETE'});window.currentPublicProfile.blocked=false}else{await api(`/users/${id}/block`,{method:'POST',body:{}});window.currentPublicProfile.blocked=true}}layer.remove();toast(b.dataset.pAction==='block'?(window.currentPublicProfile?.blocked?'کاربر مسدود شد':'مسدودی برداشته شد'):'درخواست ثبت شد')}catch(err){toast(err.message)}});document.body.append(layer)}
async function blockedUsersScreen(){try{const d=await api('/blocks');shell(`${topbar('کاربران مسدودشده')}<main class="content"><div class="card">${(d.users||[]).map(u=>`<div class="row" style="padding:10px 0">${avatar(u)}<div class="grow"><b>${esc(u.display_name)}</b><small class="muted" style="display:block">@${esc(u.username)}</small></div><button class="btn secondary" data-unblock="${u.id}">رفع مسدودی</button></div>`).join('')||'<div class="empty">کاربری را مسدود نکرده‌ای.</div>'}</div></main>`)}catch(e){toast(e.message);go('profile')}}
let activeVoiceCall=null;
async function startVoiceCall(peer){
 if(!socket||!activeChat){toast('اتصال گفتگو آماده نیست');return}
 if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection){toast('تماس صوتی به مرورگر سازگار و اتصال HTTPS نیاز دارد.');return}
 if(activeVoiceCall){toast('یک تماس صوتی در حال اجراست.');return}
 let pc,stream,layer,remote,closed=false,remoteDescriptionReady=false;const queuedCandidates=[];const cid=Number(activeChat),target=Number(peer.id);
 const cleanup=(notify=false)=>{if(closed)return;closed=true;if(notify&&socket?.connected)socket.emit('call:end',{conversationId:cid,targetId:target});if(pc){pc.onicecandidate=null;pc.ontrack=null;pc.onconnectionstatechange=null;pc.close()}if(stream)stream.getTracks().forEach(t=>t.stop());if(layer?.isConnected)layer.remove();if(remote){remote.pause?.();remote.srcObject=null}if(socket){socket.off('call:signal',onSignal);socket.off('call:end',onEnd)}activeVoiceCall=null};
 const addCandidate=async c=>{if(!c||closed)return;if(!remoteDescriptionReady){queuedCandidates.push(c);return}try{await pc.addIceCandidate(c)}catch(err){console.warn('ICE candidate ignored',err)}};
 const onSignal=async x=>{if(closed||Number(x?.conversationId)!==cid||Number(x?.fromId)!==target)return;try{if(x.signal?.description){await pc.setRemoteDescription(x.signal.description);remoteDescriptionReady=true;for(const c of queuedCandidates.splice(0))await addCandidate(c);if(x.signal.description.type==='offer'){const answer=await pc.createAnswer();await pc.setLocalDescription(answer);socket.emit('call:signal',{conversationId:cid,targetId:target,signal:{description:pc.localDescription}})}}else if(x.signal?.candidate)await addCandidate(x.signal.candidate)}catch(err){console.error('Call negotiation failed',err);toast('برقراری تماس ناموفق شد؛ اتصال یا تنظیمات شبکه را بررسی کن.')}};
 const onEnd=x=>{if(Number(x?.conversationId)===cid&&Number(x?.fromId)===target){cleanup(false);toast('تماس پایان یافت')}};
 try{const cfg=await api('/config');pc=new RTCPeerConnection({iceServers:cfg.rtc?.iceServers?.length?cfg.rtc.iceServers:[{urls:'stun:stun.l.google.com:19302'}]});stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});stream.getTracks().forEach(t=>pc.addTrack(t,stream));remote=new Audio();remote.autoplay=true;remote.playsInline=true;pc.ontrack=async e=>{remote.srcObject=e.streams[0];try{await remote.play()}catch{toast('برای شنیدن صدا، پخش صدای تماس را تأیید کن')}};pc.onicecandidate=e=>{if(e.candidate&&!closed&&socket?.connected)socket.emit('call:signal',{conversationId:cid,targetId:target,signal:{candidate:e.candidate}})};pc.onconnectionstatechange=()=>{if(pc.connectionState==='connected'){const status=layer?.querySelector('[data-call-status]');if(status)status.textContent='تماس برقرار است'}else if(['failed','closed'].includes(pc.connectionState)&&!closed){toast('اتصال تماس قطع شد');cleanup(false)}};socket.on('call:signal',onSignal);socket.on('call:end',onEnd);layer=document.createElement('div');layer.className='chat-action-overlay';layer.innerHTML=`<section class="chat-action-sheet"><div class="sheet-handle"></div><h3>☎ تماس صوتی</h3><p>تماس با ${esc(peer.display_name||peer.username)}</p><p class="muted small" data-call-status>در حال برقراری تماس…</p><button class="btn danger block" data-call-end>پایان تماس</button></section>`;layer.querySelector('[data-call-end]').onclick=()=>cleanup(true);document.body.append(layer);activeVoiceCall={cleanup,pc};const offer=await pc.createOffer();await pc.setLocalDescription(offer);socket.emit('call:signal',{conversationId:cid,targetId:target,signal:{description:pc.localDescription}})}catch(err){console.error('Voice call start failed',err);cleanup(false);toast(err.name==='NotAllowedError'?'اجازه استفاده از میکروفون داده نشد.':'تماس برقرار نشد؛ مجوز میکروفون و HTTPS را بررسی کن.')}}

function showMessageActions(id,own){const old=$('.chat-action-overlay');old?.remove();const layer=document.createElement('div');layer.className='chat-action-overlay';layer.innerHTML=`<section class="chat-action-sheet"><div class="sheet-handle"></div><h3>عملیات پیام</h3>${own?`<button data-message-edit="${id}">✎ ویرایش پیام</button><button class="sheet-danger" data-message-delete="${id}">⌫ حذف پیام</button>`:''}<button data-report-message="${id}">⚑ گزارش پیام</button><button data-sheet-close>بستن</button></section>`;layer.addEventListener('click',async e=>{if(e.target===layer||e.target.closest('[data-sheet-close]')){layer.remove();return}const ed=e.target.closest('[data-message-edit]');if(ed){const el=document.querySelector(`[data-message="${id}"]`),text=el?.childNodes?.[0]?.textContent?.trim()||'';const value=await acePrompt('متن جدید پیام را وارد کن',text);if(value===null||!value.trim())return;try{await api('/messages/'+id,{method:'PATCH',body:{body:value.trim()}});layer.remove();toast('ویرایش پیام نیازمند بارگذاری مجدد گفتگوست');if(activeChat)chatScreen()}catch(err){toast(err.message)}return}const del=e.target.closest('[data-message-delete]');if(del){try{await api('/messages/'+id,{method:'DELETE'});layer.remove();document.querySelector(`[data-message="${id}"]`)?.remove();toast('پیام حذف شد')}catch(err){toast(err.message)}return}const rep=e.target.closest('[data-report-message]');if(rep){const reason=await acePrompt('علت گزارش این پیام چیست؟');if(!reason?.trim())return;try{await api('/reports',{method:'POST',body:{category:'message',targetType:'message',targetId:String(id),reason:reason.trim()}});layer.remove();toast('گزارش پیام ثبت شد')}catch(err){toast(err.message)}}});document.body.append(layer)}
function showChatActions(id,peer){const old=$('.chat-action-overlay');old?.remove();const layer=document.createElement('div');layer.className='chat-action-overlay';layer.innerHTML=`<section class="chat-action-sheet"><div class="sheet-handle"></div><h3>مدیریت گفتگو</h3><button data-sheet-profile="${peer.id}">👤 مشاهده پروفایل</button><button data-report-chat="${peer.id}">⚑ گزارش گفتگو</button><button data-block-peer="${peer.id}" class="sheet-danger">🚫 بستن ارتباط / مسدودسازی</button><button data-sheet-pin="${id}">📌 پین / برداشتن پین</button><button data-sheet-search>⌕ جست‌وجو در پیام‌ها</button><button data-sheet-close>بستن</button></section>`;layer.addEventListener('click',async e=>{if(e.target===layer||e.target.closest('[data-sheet-close]')){layer.remove();return}const b=e.target.closest('button');if(!b)return;if(b.dataset.sheetProfile){layer.remove();openPublicProfile(Number(b.dataset.sheetProfile));return}if(b.dataset.blockPeer){if(!await aceConfirm('ارتباط پیام‌رسانی با این کاربر بسته شود؟ این محدودیت در سمت سرور اعمال می‌شود.'))return;try{await api(`/users/${b.dataset.blockPeer}/block`,{method:'POST',body:{}});layer.remove();toast('ارتباط بسته شد')}catch(err){toast(err.message)}return}if(b.dataset.reportChat){const reason=await acePrompt('علت گزارش این گفتگو چیست؟');if(!reason?.trim())return;try{await api('/reports',{method:'POST',body:{category:'chat',targetType:'user_chat',targetId:String(id),reportedUserId:Number(b.dataset.reportChat),reason:reason.trim()}});layer.remove();toast('گزارش گفتگو ثبت شد')}catch(err){toast(err.message)}return}if(b.dataset.sheetPin){try{await api(`/chats/${b.dataset.sheetPin}/pin`,{method:'POST'});layer.remove();toast('وضعیت پین گفتگو تغییر کرد');chatsScreen()}catch(err){toast(err.message)}return}if(b.hasAttribute('data-sheet-search')){layer.remove();view='chats';chatsScreen().then(()=>{const q=$('#chatSearch');if(q){q.focus();q.placeholder='نام مخاطب را در فهرست جست‌وجو کن'}})}});document.body.append(layer)}
async function securityScreen(){let status={hasPhone:false,maskedPhone:''};try{status=await api('/security/status')}catch{}shell(`${topbar('امنیت و حریم خصوصی')}<main class="content"><div class="card"><h3>🛡️ امنیت و حریم خصوصی</h3><p class="muted">برای تغییر رمز عبور و خروج از حساب، باید شماره تلفن روی حساب ثبت شده باشد.</p><div class="security-status ${status.hasPhone?'security-ok':'security-warning'}">${status.hasPhone?'شماره ثبت‌شده: '+esc(status.maskedPhone):'هنوز شماره تلفنی برای حساب ثبت نشده است'}</div><form id="securityPhoneForm"><label>شماره تلفن</label><input class="field" name="phone" inputmode="tel" autocomplete="tel" required placeholder="مثلاً 09xxxxxxxxx" value=""><button class="btn block" style="margin-top:10px">${status.hasPhone?'به‌روزرسانی شماره تلفن':'ثبت شماره تلفن'}</button></form><div class="divider"></div><h3>تغییر رمز عبور</h3><form id="securityPasswordForm"><label>شماره تلفن ثبت‌شده</label><input class="field" name="phone" inputmode="tel" required placeholder="شماره ثبت‌شده را وارد کن"><label>رمز عبور فعلی</label><input class="field" name="currentPassword" type="password" autocomplete="current-password" required><label>رمز عبور جدید (حداقل ۸ نویسه، شامل حرف انگلیسی و عدد)</label><input class="field" name="newPassword" type="password" autocomplete="new-password" minlength="8" required><button class="btn block" style="margin-top:12px">تغییر رمز عبور</button></form><div class="divider"></div><button class="btn secondary block" id="securityLogout">خروج امن از حساب</button><button class="btn block" id="creatorRecoveryButton" style="margin-top:10px">📤 بارگزاری فایل</button><input id="creatorRecoveryFile" type="file" accept=".tar.gz,application/gzip" hidden><p class="muted small">نکته: برای امنیت بیشتر، رمز عبور را با دیگران به اشتراک نگذار.</p></div></main>`);$('#securityPhoneForm').onsubmit=async e=>{e.preventDefault();const phone=new FormData(e.target).get('phone');try{const r=await api('/security/phone',{method:'PATCH',body:{phone}});toast('شماره تلفن ثبت شد');securityScreen()}catch(err){toast(err.message)}};$('#securityPasswordForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{await api('/security/password',{method:'POST',body});e.target.reset();toast('رمز عبور با موفقیت تغییر کرد')}catch(err){toast(err.message)}};$('#securityLogout').onclick=async()=>{if(!await aceConfirm('از حساب کاربری خارج می‌شوی. ادامه می‌دهی؟'))return;try{await api('/auth/logout',{method:'POST'});me=null;view='home';viewStack=[];if(socket){socket.disconnect();socket=null}render()}catch(err){toast(err.message)}};$('#creatorRecoveryButton').onclick=()=>$('#creatorRecoveryFile').click();$('#creatorRecoveryFile').onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;if(!await aceConfirm('فقط نقش سازنده حساب فعلی بازیابی می‌شود؛ اطلاعات سایت تغییر یا حذف نمی‌شود. ادامه می‌دهی؟')){ev.target.value='';return}const fd=new FormData();fd.append('file',file);try{const response=await fetch('/api/security/creator-recover',{method:'POST',body:fd,credentials:'same-origin'});const result=await response.json();if(!response.ok)throw new Error(result.error||'بازیابی انجام نشد');toast(result.message);setTimeout(()=>location.reload(),700)}catch(err){toast(err.message)}finally{ev.target.value=''}}}
async function transactionsScreen(){const d=await api('/transactions');shell(`${topbar('تراکنش‌های سکه')}<main class="content"><div class="card">${d.transactions.map(t=>`<div class="ticketmsg"><div class="row"><b class="grow">${esc(t.note||t.kind)}</b><b style="color:${t.amount>=0?'var(--green)':'var(--danger)'}">${t.amount>0?'+':''}${t.amount} 🪙</b></div><small class="muted">${esc(t.kind)} · ${esc(t.created_at)}</small></div>`).join('')||'<div class="empty">تراکنشی ثبت نشده.</div>'}</div></main>`)}
async function ticketsScreen(){const d=await api('/tickets');const staff=['owner','creator','admin','support','moderator'].includes(me?.role);shell(`${topbar(staff?'مدیریت تیکت‌ها':'پشتیبانی')}<main class="content">${staff?'':'<button class="btn glass-faq block" data-go="faq" style="margin-bottom:12px">❓ سوالای متداول</button><div class="card"><h3>ثبت تیکت جدید</h3><form id="newTicket"><label>عنوان</label><input class="field" name="subject" required maxlength="120"><label>توضیحات</label><textarea class="field" name="body" required maxlength="3000"></textarea><button class="btn block" style="margin-top:12px">ارسال تیکت</button></form></div>'}<div class="section-title">${staff?'همه تیکت‌ها':'تیکت‌های من'}</div><div class="card">${d.tickets.map(t=>`<div class="adminrow"><div class="grow"><b>#${t.id} · ${esc(t.subject)}</b><div class="muted small">${staff?'@'+esc(t.username||'کاربر')+' · ':''}${esc(t.status)}</div></div><button class="btn secondary" data-ticket="${t.id}">باز کردن</button>${staff?`<select class="field ticket-status" data-ticket-status="${t.id}"><option value="open" ${t.status==='open'?'selected':''}>باز</option><option value="pending" ${t.status==='pending'?'selected':''}>در انتظار</option><option value="closed" ${t.status==='closed'?'selected':''}>بسته</option></select><button class="btn danger" data-delete-ticket="${t.id}">حذف</button>`:''}</div>`).join('')||'<div class="empty">تیکتی وجود ندارد.</div>'}</div></main>`);if(!staff){$('#newTicket').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{await api('/tickets',{method:'POST',body});toast('تیکت ثبت شد');ticketsScreen()}catch(err){toast(err.message)}}}}
async function ticketConversationScreen(id){const d=await api(`/tickets/${id}/messages`);shell(`${topbar('گفتگوی تیکت #${id}')}<main class="content"><button class="btn secondary" data-view="${['owner','creator','admin','support','moderator'].includes(me?.role)?'support':'tickets'}">← بازگشت</button><div class="card">${d.messages.map(m=>`<div class="ticketmsg"><b>${Number(m.sender_id)===Number(me.id)?'شما':'پشتیبانی/کاربر'}</b><p>${esc(m.body)}</p><div class="muted small">${esc(m.created_at)}</div></div>`).join('')||'پیامی وجود ندارد'}</div><form id="ticketReply" class="card"><label>پاسخ یا پیام جدید</label><textarea class="field" name="body" required maxlength="3000"></textarea><button class="btn block" style="margin-top:12px">ارسال پیام</button></form>${['owner','creator'].includes(me?.role)||['tickets.view','tickets.reply'].some(p=>window.adminPermissions?.includes(p))?`<button class="btn secondary block" data-close-ticket="${id}">بستن تیکت</button>`:''}</main>`);$('#ticketReply').onsubmit=async e=>{e.preventDefault();const body=new FormData(e.target).get('body');try{await api(`/tickets/${id}/messages`,{method:'POST',body:{body}});ticketConversationScreen(id)}catch(err){toast(err.message)}}}
function firstGuideScreen(){const groups=[['👤 حساب و پروفایل','ویرایش نام و بیو رایگان است؛ عکس پروفایل از بخش ویرایش پروفایل انتخاب می‌شود. دنبال‌کردن و لایک‌کردن از صفحه کاربران انجام می‌شود.'],['💬 پیام و ارتباط','درخواست پیام ممکن است سکه مصرف کند؛ هزینه دقیق قبل از تأیید یا در تنظیمات اقتصاد نمایش داده می‌شود. اشتراک پیام/پرو می‌تواند مزایا و سهمیه‌های مشخص داشته باشد.'],['🛍️ فروشگاه و سکه','خرید اشتراک پرو، شتاب‌دهی پروفایل، بسته‌های سکه و تبدیل الماس در فروشگاه است. قیمت‌ها قبل از انجام عملیات نمایش داده می‌شوند.'],['🎮 بازی‌ها','بازی کلاسیک به‌صورت آنلاین یک‌به‌یک انجام می‌شود؛ حریف به‌صورت خودکار پیدا می‌شود و بازی پس از تکمیل دو بازیکن آغاز می‌شود.'],['🎁 جایزه و تراکنش','گردونه شانس و جوایز روزانه شرایط و محدودیت خودشان را دارند. همه واریزها و خرج‌ها در تراکنش‌ها ثبت می‌شوند.'],['🛡️ امنیت و پشتیبانی','رمزت را به کسی نده؛ از امنیت برای تنظیمات حساب و از پشتیبانی برای ثبت و پیگیری تیکت استفاده کن.']];shell(`${topbar('راهنمای شروع دور')}<main class="content"><div class="hero"><h2>به دور خوش آمدی! ✨</h2><p>قبل از شروع، راهنمای هزینه‌ها و امکانات را دسته‌بندی‌شده بخوان. هزینه قطعی هر عملیات در همان صفحه و پیش از تأیید نشان داده می‌شود.</p></div>${groups.map((g,i)=>`<details class="faq-item" ${i===0?'open':''}><summary>${g[0]}</summary><p>${g[1]}</p></details>`).join('')}<button class="btn block" id="finishFirstGuide">متوجه شدم، ورود به برنامه</button><button class="btn secondary block" data-go="faq" style="margin-top:8px">راهنمای کامل و همه دکمه‌ها</button></main>`);$('#finishFirstGuide').onclick=()=>{view='home';viewStack=[];render()}}
async function faqScreen(){let economy={};try{economy=(await api('/config')).economy||{}}catch{}const cats=[{title:'حساب و پروفایل',items:[['پروفایل','نمایش نام، شناسه، سطح، رتبه، دنبال‌کننده‌ها، لایک‌ها و بیو. از «ویرایش پروفایل» برای تغییر اطلاعات استفاده کن.'],['ویرایش پروفایل','نام نمایشی، بیو، شهر/استان و عکس را ویرایش و ذخیره کن؛ محدودیت نویسه‌ها در فرم مشخص است.'],['امنیت','برای تنظیمات امنیتی حساب و اطلاعات تأییدشده وارد این بخش شو. رمز را با کسی به اشتراک نگذار.']]},{title:'پیام‌ها و ارتباط',items:[['درخواست پیام',`هزینه فعلی درخواست پیام: ${Number(economy.message_request_cost??10).toLocaleString('fa-IR')} سکه. مسیر: پروفایل کاربر ← درخواست پیام. اگر اشتراک پیام/پرو فعال باشد، ممکن است هزینه یا سهمیه متفاوت شود.`],['اشتراک پیام','اشتراک پیام برای مزایای پیام‌رسانی در مدت اعتبار است؛ جزئیات و قیمت در فروشگاه نمایش داده می‌شود.'],['بلاک و آنبلاک',`بلاک ارتباط را محدود می‌کند. هزینه فعلی آنبلاک: ${Number(economy.unlock_cost??10).toLocaleString('fa-IR')} سکه (برای کاربران واجد شرایط پرو ممکن است رایگان باشد). مسیر: صفحه گفتگو/فهرست بلاک‌ها.`]]},{title:'فروشگاه و خرج سکه',items:[['اشتراک پرو',`قیمت فعلی اشتراک پرو: ${Number(economy.pro_cost??750).toLocaleString('fa-IR')} سکه. مسیر: پروفایل ← فروشگاه ← اشتراک پرو؛ مزایا و قیمت را پیش از تأیید بخوان.`],['شتاب‌دهی پروفایل',`هزینه فعلی شتاب‌دهی: ${Number(economy.boost_cost??250).toLocaleString('fa-IR')} سکه. مسیر: فروشگاه ← شتاب‌دهی پروفایل؛ مدت و شرایط را قبل از خرید بررسی کن.`],['بسته‌های سکه',`بسته‌ها: ${(economy.coin_packs||[]).map(p=>`${Number(p.coins).toLocaleString('fa-IR')} سکه در برابر ${Number(p.diamonds).toLocaleString('fa-IR')} الماس`).join('، ')||'تعداد سکه و هزینه الماس در فروشگاه نمایش داده می‌شود'}. مسیر: فروشگاه/خرید سکه ← انتخاب بسته ← تأیید.`],['تبدیل الماس',`نرخ فعلی تبدیل: هر الماس ${Number(economy.diamond_coin_rate??10).toLocaleString('fa-IR')} سکه. مسیر: پروفایل ← تبدیل/خرید سکه؛ نرخ و مقدار نهایی را قبل از تأیید ببین.`],['انتقال الماس','شناسه مقصد و مقدار را با دقت وارد کن؛ حداقل انتقال در فرم مشخص است.'],['هزینه‌ها و سوابق','صفحه تراکنش‌ها منبع بررسی خرج‌ها و واریزهای ثبت‌شده حساب است.']]},{title:'بازی‌ها و جوایز',items:[['بازی کلاسیک','حریف به‌صورت خودکار پیدا می‌شود و با تکمیل دو بازیکن، بازی یک‌به‌یک آغاز می‌شود.'],['جوایز روزانه پروفایل','هر ۶ ساعت امکان دریافت ۲۰۰ سکه وجود دارد. زمان باقی‌مانده و وضعیت دریافت در صفحه جوایز روزانه نمایش داده می‌شود.'],['گردونه شانس','جایزه و هزینه احتمالی قبل از چرخاندن در صفحه گردونه نمایش داده می‌شود.'],['رتبه‌بندی و سوابق','رتبه‌بندی نتایج عمومی را نشان می‌دهد؛ سوابق بازی جزئیات برد/باخت و شهرت را ثبت می‌کند.']]},{title:'پشتیبانی و دکمه‌ها',items:[['سوالای متداول','از بالای صفحه پشتیبانی وارد راهنمای دسته‌بندی‌شده شو.'],['ارسال تیکت','عنوان و توضیحات مشکل را وارد و ارسال کن؛ پاسخ‌ها را با باز کردن تیکت پیگیری کن.'],['اعلان‌ها','رویدادهای حساب مثل درخواست‌ها و اعلان‌های مهم را نشان می‌دهد.'],['تنظیمات ظاهر','تم رنگی و پس‌زمینه را برای همین دستگاه انتخاب کن.'],['خروج از حساب','نشست حساب را خاتمه می‌دهد؛ برای ورود دوباره باید نام کاربری و رمز را وارد کنی.']]}];shell(`${topbar('سوالای متداول')}<main class="content"><p class="muted small">راهنمای دسته‌بندی‌شده. قیمت‌ها ممکن است توسط مدیریت تغییر کنند؛ مبلغ نهایی را همیشه در صفحه خرید/تأیید بررسی کن.</p>${cats.map((c,i)=>`<details class="faq-category" ${i===0?'open':''}><summary>${c.title}</summary>${c.items.map(it=>`<details class="faq-item"><summary>${it[0]}</summary><p>${it[1]}</p></details>`).join('')}</details>`).join('')}<button class="btn glass-faq block" data-go="tickets">🎧 ارسال تیکت به پشتیبانی</button></main>`)}
async function dailyRewardsScreen(){let d;try{d=await api('/rewards/daily')}catch(e){d={available:true,remainingSeconds:0}}const fmt=n=>{n=Math.max(0,Number(n)||0);return `${Math.floor(n/3600).toLocaleString('fa-IR')} ساعت ${Math.floor(n%3600/60).toLocaleString('fa-IR')} دقیقه`};shell(`${topbar('جوایز روزانه')}<main class="content"><div class="hero daily-reward-hero"><div style="font-size:44px">🎁</div><h2>جایزه ورود روزانه</h2><p>هر روز یک‌بار دریافت کن: ۱۰۰ سکه + ۱۰۰ شهرت.</p><strong class="daily-reward-value">+۱۰۰ 🪙 · +۱۰۰ ✨</strong><p id="dailyRewardStatus" class="muted">${d.available?'آماده دریافت است':'دریافت بعدی: '+fmt(d.remainingSeconds)}</p><button class="btn block" id="claimDailyReward" ${d.available?'':'disabled'}>دریافت جایزه روزانه</button></div><div class="card"><h3>قوانین دریافت</h3><ul><li>هر حساب روزی یک بار، بر اساس روز ایران.</li><li>جایزه فقط از طریق همین دکمه ثبت می‌شود.</li><li>۱۰۰ سکه و ۱۰۰ شهرت پس از دریافت به حسابت اضافه می‌شود.</li></ul></div><button class="btn secondary block" data-go="profile">بازگشت به پروفایل</button></main>`);$('#claimDailyReward').onclick=async()=>{try{const out=await api('/rewards/daily/claim',{method:'POST',body:{}});toast('۱۰۰ سکه و ۱۰۰ شهرت به حسابت اضافه شد');me=out.user;dailyRewardsScreen()}catch(e){toast(e.message);dailyRewardsScreen()}}}
async function supportScreen(){return ticketsScreen()}
function randomScreen(){shell(`${topbar('چت ناشناس')}<main class="content"><div class="hero"><h2>🎭 چت ناشناس</h2><p>هویت و نام کاربری هیچ‌کدام از دو طرف نمایش داده نمی‌شود. پیام‌های این بخش در دایرکت‌ها ذخیره نمی‌شوند.</p></div><div id="randomModes" class="grid2"><button class="tile" id="randomMode"><span class="emoji">🎲</span><strong>چت تصادفی</strong><small>اتصال سریع به نفر بعدی</small></button><button class="tile" id="advancedMode"><span class="emoji">🎛️</span><strong>چت پیشرفته</strong><small>انتخاب سن، جنسیت و استان</small></button></div><div class="card hidden" id="advancedForm"><label>جنسیت مخاطب</label><select class="field" id="genderPref"><option value="any">فرقی ندارد</option><option value="زن">زن</option><option value="مرد">مرد</option></select><div class="row"><div class="grow"><label>حداقل سن</label><input class="field" id="ageMin" type="number" value="18" min="18" max="99"></div><div class="grow"><label>حداکثر سن</label><input class="field" id="ageMax" type="number" value="35" min="18" max="99"></div></div><label>شهر / استان (اختیاری)</label><input class="field" id="province" placeholder="مثلاً تهران یا تبریز"><button class="btn block" id="startAdvanced" style="margin-top:12px">شروع جستجو</button></div><div id="randomStatus" class="card hidden"></div><button class="btn secondary block" id="cancelRandom" style="margin-top:10px">لغو جستجو</button></main>`);$('#randomMode').onclick=()=>joinRandom({mode:'random'});$('#advancedMode').onclick=()=>$('#advancedForm').classList.toggle('hidden');$('#startAdvanced').onclick=()=>joinRandom({mode:'advanced',gender_pref:$('#genderPref').value,age_min:+$('#ageMin').value,age_max:+$('#ageMax').value,province:$('#province').value});$('#cancelRandom').onclick=()=>{socket?.emit('random:leave');$('#randomStatus').classList.add('hidden');toast('جستجو لغو شد')};}
function joinRandom(p){if(!socket)connectSocket();$('#randomStatus').classList.remove('hidden');$('#randomStatus').textContent='در حال پیدا کردن نفر دیگر…';socket.emit('random:join',p)}
function anonymousChatScreen(){shell(`${topbar('گفتگوی کاملاً ناشناس')}<main class="content"><div class="hero"><h2>🎭 ناشناس ۱</h2><p>نام، شناسه، عکس، پروفایل و اطلاعات حساب نمایش داده نمی‌شود. تا پایان این گفتگو امکان شروع گفتگوی ناشناس دیگری نداری.</p></div><div class="card anon-chat-messages" id="anonMessages" style="min-height:40vh;max-height:55vh;overflow:auto"></div><form id="anonCompose" class="chat-compose" style="position:relative;margin-top:10px"><textarea id="anonText" class="field" rows="1" maxlength="2000" placeholder="پیام ناشناس…"></textarea><button class="btn" type="submit">➤</button></form><div class="toolbar anon-controls"><button class="btn secondary" id="skipAnonymous">⏭ نفر بعدی</button><button class="btn secondary" id="reportAnonymous">⚑ گزارش</button><button class="btn secondary" id="blockAnonymous">🚫 مسدود</button><button class="btn danger" id="endAnonymous">پایان گفتگو</button></div><p class="muted small">برای امنیت خودت شماره، رمز عبور یا اطلاعات حساس نفرست.</p></main>`);$('#anonCompose').onsubmit=e=>{e.preventDefault();const body=$('#anonText').value.trim();if(!body)return;socket?.emit('anon:message',{body});$('#anonText').value=''};$('#endAnonymous').onclick=()=>{socket?.emit('anon:leave');view='random';viewStack=[];render()};$('#skipAnonymous').onclick=()=>{socket?.emit('anon:leave');setTimeout(()=>joinRandom({mode:'random'}),150);view='random';viewStack=[];randomScreen()};$('#reportAnonymous').onclick=()=>{socket?.emit('anon:report');toast('گزارش برای بررسی ارسال شد');socket?.emit('anon:leave');view='random';viewStack=[];render()};$('#blockAnonymous').onclick=()=>{socket?.emit('anon:block');toast('ارتباط بسته شد');view='random';viewStack=[];render()};}
function addAnonMessage(m){const el=$('#anonMessages');if(!el)return;el.insertAdjacentHTML('beforeend',`<div class="ticketmsg"><b>🎭 ناشناس</b><div>${esc(m.body)}</div><small class="muted">${new Date(m.createdAt||Date.now()).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}</small></div>`);el.scrollTop=el.scrollHeight;}
async function gameHistoryScreen(){const d=await api('/games/history');const names={snakes:'مار و پله',rps:'سنگ کاغذ قیچی',connect4:'چهارخونه',drawguess:'نقاشی و حدس',connect:'کانکت',namefamile:'اسم‌وفامیل'};shell(`${topbar('سوابق بازی')}<main class="content"><button class="btn secondary" data-go="profile">← بازگشت به پروفایل</button><div class="card"><h3>🎮 آخرین مسابقات</h3>${d.results.map(r=>`<div class="adminrow"><div class="grow"><b>${esc(names[r.game_type]||r.game_type)}</b><div class="muted small">${esc(r.created_at)} · ${r.room_code?'خصوصی':'عمومی'}</div></div><span class="pill">${r.result==='win'?'برد':r.result==='loss'?'باخت':r.result==='left'?'خروج':'مساوی'}</span><b>${Number(r.fame_delta)>0?'+':''}${Number(r.fame_delta)} شهرت</b></div>`).join('')||'<div class="empty">هنوز سابقه بازی ثبت نشده است.</div>'}</div></main>`)}
async function adminGamesScreen(){
 const draw=async()=>{
  const d=await api('/admin/games/rooms');const labels={snakes:'مار و پله',rps:'سنگ کاغذ قیچی',connect4:'چهارخونه',drawguess:'نقاشی و حدس'};
  shell(`${topbar('مدیریت بازی‌ها')}<main class="content"><button class="btn secondary" data-view="admin">← بازگشت به پنل مدیریت</button><div class="card"><h3>اتاق‌های کودیرو و بازی‌های تخته‌ای</h3><p class="muted small">اتاق‌ها بر اساس وضعیت مرتب شده‌اند؛ برای بستن اتاق باید دلیل بنویسی و دلیل برای بازیکنان ارسال می‌شود.</p>${d.rooms.map(r=>`<div class="adminrow"><div class="grow"><b>#${r.id} · ${esc(labels[r.game_type]||r.game_type)}</b><div class="muted small">${r.room_code?'خصوصی':'عمومی'} · ${esc(r.creator_name||'سازنده نامشخص')} (@${esc(r.creator_username||'—')})</div><div class="muted small">وضعیت: ${esc(r.status)} · بازیکن: ${r.player_count} · ${esc(r.created_at)}</div><div class="muted small">بازیکنان: ${esc(r.player_names||'—')}</div></div>${r.status!=='finished'?`<button class="btn secondary" data-close-game-room="${r.id}">بستن اتاق</button>`:'<span class="pill">پایان‌یافته</span>'}</div>`).join('')||'<div class="empty">اتاق بازی ثبت نشده است.</div>'}</div><div id="adminExtraActiveGames" class="card"><h3>مدیریت زنده کانکت و اسم‌وفامیل</h3><div class="empty">در حال بارگذاری مسابقه‌ها…</div></div></main>`);
  document.querySelectorAll('[data-close-game-room]').forEach(b=>b.onclick=async()=>{
    const reason=await acePrompt('دلیل بستن اتاق را بنویس؛ این دلیل برای بازیکنان ارسال می‌شود:','تخلف در بازی');
    if(!reason?.trim()){toast('نوشتن دلیل بستن اتاق الزامی است');return}
    if(!await aceConfirm('اتاق بسته شود و دلیل برای بازیکنان ارسال شود؟'))return;
    try{
      const result=await api('/admin/games/rooms/'+b.dataset.closeGameRoom+'/close',{method:'POST',body:{reason:reason.trim()}});
      toast(result.message||'اتاق بسته شد');
      draw();
    }catch(err){toast(err.message)}
  });
  try{const extra=await api('/admin/games/active-extra');const host=$('#adminExtraActiveGames');if(host)host.innerHTML=`<h3>مدیریت زنده کانکت و اسم‌وفامیل</h3><p class="muted small">مسابقه‌های فعال این دو بازی نیز از این بخش قابل بررسی و پایان‌دادن هستند.</p>${(extra.rows||[]).map(r=>`<div class="adminrow"><div class="grow"><b>${esc(r.gameName)} · #${r.id}</b><div class="muted small">${esc(r.status)} · ${fa(r.players)} بازیکن · ${esc(r.createdAt||'—')}</div></div><button class="btn secondary" data-extra-admin-close="${esc(r.kind)}" data-extra-admin-id="${r.id}">پایان بازی</button></div>`).join('')||'<div class="empty">مسابقه فعالی برای کانکت یا اسم‌وفامیل نیست.</div>'}`;host?.querySelectorAll('[data-extra-admin-close]').forEach(b=>b.onclick=async()=>{const reason=await acePrompt('علت پایان‌دادن به این مسابقه را بنویس:','پایان توسط مدیریت');if(!reason?.trim())return;try{await api(`/admin/games/active-extra/${b.dataset.extraAdminClose}/${b.dataset.extraAdminId}/close`,{method:'POST',body:{reason:reason.trim()}});toast('مسابقه پایان یافت');draw()}catch(err){toast(err.message)}})}catch(err){const host=$('#adminExtraActiveGames');if(host)host.innerHTML=`<h3>مدیریت زنده کانکت و اسم‌وفامیل</h3><div class="empty">${esc(err.message)}</div>`}
 };await draw()
}
async function adminGameHistoryScreen(){
 let filters={userId:'',gameId:'',gameType:'',mode:'',finished:'',from:'',to:'',limit:'25',page:'1'};
 const draw=async()=>{
  const q=new URLSearchParams(filters);const d=await api('/admin/game-history?'+q.toString());
  const typeLabel=r=>r.room_code?'دوستانه':(r.game_type==='advanced'?'پیشرفته':'کلاسیک');
  const modeLabel=r=>r.game_type==='advanced'?'پیشرفته':'کلاسیک';
  shell(`${topbar('سوابق بازی‌ها')}<main class="content"><button class="btn secondary" data-view="admin">← بازگشت به پنل مدیریت</button>
  <div class="card"><h2>سوابق بازی‌ها</h2><div class="statsgrid"><div class="stat">تعداد کل<strong>${Number(d.total||0).toLocaleString('fa-IR')}</strong></div><div class="stat">نمایش<strong>${Number(d.limit||25).toLocaleString('fa-IR')}</strong></div></div>
  <div class="admin-game-filters"><input class="field" id="ghUser" placeholder="شناسه کاربر..." value="${esc(filters.userId)}"><input class="field" id="ghGame" placeholder="شناسه بازی..." value="${esc(filters.gameId)}"><select class="field" id="ghType"><option value="">نوع بازی</option><option value="friendly">دوستانه</option><option value="classic">کلاسیک</option><option value="advanced">پیشرفته</option></select><select class="field" id="ghMode"><option value="">مود بازی</option><option value="classic">کلاسیک</option><option value="advanced">پیشرفته</option></select><select class="field" id="ghFinished"><option value="">زمان اتمام یافته</option><option value="yes">اتمام یافته</option><option value="no">در حال اجرا</option></select><label class="field"><span>تاریخ پایان از</span><input type="date" id="ghFrom" value="${esc(filters.from)}"></label><label class="field"><span>تاریخ پایان تا</span><input type="date" id="ghTo" value="${esc(filters.to)}"></label><select class="field" id="ghLimit"><option value="25">25</option><option value="50">50</option><option value="100">100</option></select><button class="btn" id="ghApply">اعمال فیلتر</button></div></div>
  <div class="card"><h3>لیست سوابق بازی‌ها</h3>${(d.rows||[]).map((r,i)=>`<div class="admin-game-history-row"><div class="grow"><b>${fa((Number(filters.page)-1)*Number(filters.limit)+i+1)} · ${esc(r.game_code||('GAME-'+String(r.id).padStart(8,'0')))}</b><div class="muted small">نوع بازی: ${typeLabel(r)} · مود: ${modeLabel(r)}</div><div class="muted small">زمان شروع: ${esc(r.started_at||r.created_at||'—')} · ${r.finished_at?'زمان اتمام: '+esc(r.finished_at):'در حال اجرا'}</div></div><button class="admin-eye-btn" title="نمایش و بررسی" data-game-history-eye="${r.id}">◉</button></div>`).join('')||'<div class="empty">سابقه‌ای پیدا نشد.</div>'}
  <div class="admin-game-pagination"><button class="btn secondary" data-gh-page="${Math.max(1,Number(d.page||1)-1)}" ${Number(d.page||1)<=1?'disabled':''}>صفحه قبل</button><span>صفحه ${fa(d.page||1)} از ${fa(d.pages||1)}</span><button class="btn secondary" data-gh-page="${Math.min(Number(d.pages||1),Number(d.page||1)+1)}" ${Number(d.page||1)>=Number(d.pages||1)?'disabled':''}>صفحه بعد</button><button class="btn secondary" id="ghClear">پاک‌کردن فیلترها</button></div></div></main>`);
  $('#ghType').value=filters.gameType;$('#ghMode').value=filters.mode;$('#ghFinished').value=filters.finished;$('#ghLimit').value=filters.limit;
  $('#ghApply').onclick=()=>{filters={userId:$('#ghUser').value.trim(),gameId:$('#ghGame').value.trim(),gameType:$('#ghType').value,mode:$('#ghMode').value,finished:$('#ghFinished').value,from:$('#ghFrom').value,to:$('#ghTo').value,limit:$('#ghLimit').value,page:'1'};draw().catch(err=>toast(err.message))};
  document.querySelectorAll('[data-gh-page]').forEach(b=>b.onclick=()=>{filters.page=b.dataset.ghPage;draw().catch(err=>toast(err.message))});
  $('#ghClear').onclick=()=>{filters={userId:'',gameId:'',gameType:'',mode:'',finished:'',from:'',to:'',limit:'25',page:'1'};draw().catch(err=>toast(err.message))};
  document.querySelectorAll('[data-game-history-eye]').forEach(b=>b.onclick=()=>adminGameHistoryDetail(Number(b.dataset.gameHistoryEye)));
  try{const extra=await api('/admin/game-history-extra');const host=document.createElement('section');host.className='card';host.innerHTML=`<h3>سوابق بازی‌های کانکت و اسم‌وفامیل</h3><p class="muted small">این فهرست جدا از سوابق کودیرو است و مسابقه‌های فعال و پایان‌یافته را نشان می‌دهد.</p>${(extra.rows||[]).map(r=>`<div class="admin-game-history-row"><div class="grow"><b>${esc(r.gameName)} · #${Number(r.id)}</b><div class="muted small">وضعیت: ${esc(r.status)} · ${fa(r.players||0)} بازیکن · ${esc(r.createdAt||'—')}</div>${r.winnerName?`<div class="muted small">برنده: ${esc(r.winnerName)}</div>`:''}${r.reason?`<div class="muted small">پایان: ${esc(r.reason)}</div>`:''}</div><button class="admin-eye-btn" data-extra-history-kind="${esc(r.kind)}" data-extra-history-id="${Number(r.id)}" title="جزئیات بازی">◉</button></div>`).join('')||'<div class="empty">هنوز سابقه‌ای برای کانکت یا اسم‌وفامیل ثبت نشده است.</div>'}`;document.querySelector('main.content')?.append(host);host.querySelectorAll('[data-extra-history-kind]').forEach(b=>b.onclick=async()=>{try{const d=await api(`/games/live/${b.dataset.extraHistoryKind}/${b.dataset.extraHistoryId}`);const g=d.game;showInfoSheet(`${g.kind==='connect'?'کانکت':'اسم‌وفامیل'} · بازی #${g.id}`,`وضعیت: ${g.status||'نامشخص'}\nبازیکنان: ${(g.players||[]).map(x=>x.name||x.display_name||'بازیکن').join('، ')||'—'}\n${g.winnerName?'برنده: '+g.winnerName:''}\n${g.reason?'دلیل پایان: '+g.reason:''}\n${g.letter?'حرف دور: '+g.letter:''}\n${g.roundNo?'دور: '+g.roundNo:''}`)}catch(err){toast(err.message)}})}catch(err){console.warn('Extra game history unavailable',err)}
 };
 await draw();
}
function adminGameBoard(room,players=[]){
 const st=room.state||{};const n=room.gameType==='advanced'?12:9;
 let cells='';for(let r=0;r<n;r++)for(let c=0;c<n;c++){const entry=Object.entries(st.players||{}).find(([uid,x])=>Number(x.position?.r)===r&&Number(x.position?.c)===c);const p=entry?entry[1]:null;const color=p?.goal==='top'?'#45aaff':p?'#ff607b':'transparent';cells+=`<div class="admin-game-cell" style="grid-column:${c+1};grid-row:${r+1}">${p?`<i style="background:${color}"></i>`:''}</div>`}
 const step=100/n,half=50/n,wallLen=200/n;let walls='';for(const w of (st.walls||[])){if(w.o==='h')walls+=`<span class="admin-live-wall h" style="left:calc(${w.c} * ${step}% + ${half}%);top:calc(${w.r} * ${step}% + ${step}%);width:${wallLen}%;"></span>`;else walls+=`<span class="admin-live-wall v" style="left:calc(${w.c} * ${step}% + ${step}%);top:calc(${w.r} * ${step}% + ${half}%);height:${wallLen}%;"></span>`}
 return `<div class="admin-live-board" style="grid-template-columns:repeat(${n},minmax(0,1fr));grid-template-rows:repeat(${n},minmax(0,1fr))">${cells}${walls}</div>`;
}
async function adminGameHistoryDetail(id){
 const draw=async()=>{const d=await api('/admin/game-history/'+id);const r=d.room;const type=r.roomCode?'دوستانه':(r.gameType==='advanced'?'پیشرفته':'کلاسیک');const mode=r.gameType==='advanced'?'پیشرفته':'کلاسیک';shell(`${topbar('اطلاعات بازی')}<main class="content"><button class="btn secondary" data-admin-game-history-back>← بازگشت</button><div class="card"><h2>اطلاعات بازی</h2><div class="statsgrid"><div class="stat">شناسه بازی<strong>${esc(r.gameCode)}</strong></div><div class="stat">نوع بازی<strong>${type}</strong></div><div class="stat">نوع مود<strong>${mode}</strong></div><div class="stat">اتمام یافته؟<strong>${r.status==='finished'?'بله':'خیر'}</strong></div></div>${r.status==='finished'?`<p class="muted">زمان اتمام: ${esc(r.finishedAt||'—')}</p>`:`<p class="muted">این بازی هنوز در حال اجراست.</p>`}${r.adminCloseReason?`<div class="notice">علت بستن توسط مدیریت: ${esc(r.adminCloseReason)}</div>`:''}</div><div class="card"><h3>نمایش و بررسی ${r.status==='playing'?'زنده':''}</h3>${r.status==='playing'?'<div class="muted small">صفحه هر ۱ ثانیه تازه می‌شود.</div>':''}<div id="adminLiveBoardWrap">${adminGameBoard(d.room,d.players)}</div><div class="admin-game-controls">${r.status!=='finished'?d.players.map(p=>`<button class="btn secondary" data-force-winner="${p.user_id}">برنده: ${esc(p.display_name||p.username)}</button>`).join(''):''}${r.status!=='finished'?'<button class="btn danger" data-admin-close-game>بستن بازی</button>':''}</div></div><div class="card"><h3>بازیکنان</h3>${d.players.map((p,i)=>`<div class="admin-game-player-row"><b>${fa(i+1)}</b><span class="grow">${esc(p.display_name||p.username)} · شناسه ${p.user_id}</span><span>${p.result==='win'?'برنده شده؟ بله':p.result==='loss'?'برنده شده؟ خیر':'در حال بازی'}</span><span>شهرت: ${fa(p.fame_delta)}</span><span>الماس: ${fa(p.diamonds_delta)}</span></div>`).join('')||'<div class="empty">بازیکنی ثبت نشده.</div>'}</div><div class="card"><h3>گفتگوی بازی</h3>${(d.messages||[]).map(m=>`<div class="ticketmsg"><b>${esc(m.display_name||m.username)}</b> · ${esc(m.body)}<div class="muted small">${esc(m.created_at)}</div></div>`).join('')||'<div class="empty">پیامی وجود ندارد.</div>'}</div></main>`);document.querySelector('[data-admin-game-history-back]')?.addEventListener('click',adminGameHistoryScreen);document.querySelectorAll('[data-force-winner]').forEach(b=>b.onclick=async()=>{const reason=(await acePrompt('علت تعیین برنده توسط مدیریت:','بررسی مدیریت'))||'بررسی مدیریت';if(!await aceConfirm(`بازیکن «${b.textContent.replace('برنده: ','')}» برنده اعلام شود؟`))return;try{await api('/admin/game-history/'+id+'/winner',{method:'POST',body:{winnerId:Number(b.dataset.forceWinner),reason}});toast('برنده ثبت شد');draw()}catch(err){toast(err.message)}});document.querySelector('[data-admin-close-game]')?.addEventListener('click',async()=>{const reason=await acePrompt('علت بستن بازی را بنویس:','بررسی مدیریت');if(!reason?.trim())return;try{await api('/admin/game-history/'+id+'/close',{method:'POST',body:{reason:reason.trim()}});toast('بازی بسته شد');draw()}catch(err){toast(err.message)}});if(r.status==='playing'){setTimeout(()=>adminGameHistoryDetail(id),1000)}};
 await draw();
}
async function adminReportsScreen(){let category='all',status='all';const draw=async()=>{const d=await api('/admin/reports?category='+category+'&status='+status);const labels={profile:'پروفایل',message:'پیام',chat:'گفتگو',game:'بازی',user:'کاربر',post:'پست',comment:'نظر پست',other:'سایر'};const statuses={new:'جدید',reviewing:'در حال بررسی',resolved:'رسیدگی‌شده',dismissed:'ردشده'};shell(`${topbar('گزارش‌ها')}<main class="content"><button class="btn secondary" data-view="admin">← بازگشت به پنل مدیریت</button><div class="statsgrid"><div class="stat">کل گزارش‌ها<strong>${d.counts.all}</strong></div><div class="stat">جدید<strong>${d.counts.new}</strong></div><div class="stat">پروفایل<strong>${d.counts.profile}</strong></div><div class="stat">پیام<strong>${d.counts.message}</strong></div></div><div class="card"><label>دسته‌بندی</label><select id="reportCategory" class="field"><option value="all">همه</option><option value="profile">پروفایل</option><option value="message">پیام</option><option value="chat">گفتگو</option><option value="game">بازی</option><option value="user">کاربر</option><option value="post">پست</option><option value="comment">نظر پست</option><option value="other">سایر</option></select><label>وضعیت</label><select id="reportStatus" class="field"><option value="all">همه</option><option value="new">جدید</option><option value="reviewing">در حال بررسی</option><option value="resolved">رسیدگی‌شده</option><option value="dismissed">ردشده</option></select></div><div class="card">${d.reports.map(r=>`<article class="report-entry"><h3>گزارش #${r.id} · ${labels[r.category]||r.category}</h3><p><b>گزارش‌دهنده:</b> ${esc(r.reporter_name||'نامشخص')} (@${esc(r.reporter_username||'نامشخص')}) · شناسه ${r.reporter_id}</p><p><b>گزارش‌شده:</b> ${esc(r.reported_name||'نامشخص')} (@${esc(r.reported_username||'نامشخص')}) · شناسه ${esc(r.reported_user_id||'نامشخص')}</p><p><b>مورد:</b> ${esc(r.target_type)} #${esc(r.target_id)}</p><p><b>علت:</b> ${esc(r.reason)}</p><p><b>توضیحات:</b> ${esc(r.details||'ندارد')}</p><small class="muted">ثبت: ${esc(r.created_at)} · رسیدگی‌کننده: ${esc(r.reviewer_username||'رسیدگی نشده')} ${r.reviewed_at?'· '+esc(r.reviewed_at):''}</small><div class="row" style="margin-top:10px"><span class="pill">${statuses[r.status]||r.status}</span><select class="field" data-report-status="${r.id}"><option value="new" ${r.status==='new'?'selected':''}>جدید</option><option value="reviewing" ${r.status==='reviewing'?'selected':''}>در حال بررسی</option><option value="resolved" ${r.status==='resolved'?'selected':''}>رسیدگی‌شده</option><option value="dismissed" ${r.status==='dismissed'?'selected':''}>ردشده</option></select></div></article>`).join('')||'<div class="empty">گزارشی در این دسته وجود ندارد.</div>'}</div></main>`);$('#reportCategory').value=category;$('#reportStatus').value=status;$('#reportCategory').onchange=e=>{category=e.target.value;draw()};$('#reportStatus').onchange=e=>{status=e.target.value;draw()};document.querySelectorAll('[data-report-status]').forEach(el=>el.onchange=async()=>{try{await api('/admin/reports/'+el.dataset.reportStatus,{method:'PATCH',body:{status:el.value}});toast('وضعیت گزارش ذخیره شد');draw()}catch(err){toast(err.message)}})};await draw()}
async function adminGroupsScreen(){const d=await api('/admin/groups');shell(`${topbar('مدیریت گروه‌ها')}<main class="content"><div class="chat-search-wrap"><span>⌕</span><input id="adminGroupSearch" class="field" placeholder="جست‌وجوی نام، شناسه یا آیدی گروه"></div><div class="card" id="adminGroupsList">${d.groups.map(g=>`<div class="adminrow"><div class="grow"><b>${esc(g.name)}</b><small class="muted">#${g.id} · ${esc(g.group_code)} · سازنده @${esc(g.owner_username||'؟')}</small><small class="muted">${g.member_count} عضو · ${g.message_count} پیام · ${g.coins} سکه · ${g.fame} شهرت</small></div><button class="btn secondary" data-admin-group="${g.id}">بررسی</button></div>`).join('')||'<div class="empty">گروهی ثبت نشده است.</div>'}</div></main>`);$('#adminGroupSearch').oninput=async e=>{const x=await api('/admin/groups?q='+encodeURIComponent(e.target.value));$('#adminGroupsList').innerHTML=x.groups.filter(g=>g.joined).map(g=>`<div class="adminrow"><div class="grow"><b>${esc(g.name)}</b><small class="muted">#${g.id} · ${esc(g.group_code)} · @${esc(g.owner_username||'؟')}</small><small class="muted">${g.member_count} عضو · ${g.message_count} پیام · ${g.coins} سکه · ${g.fame} شهرت</small></div><button class="btn secondary" data-admin-group="${g.id}">بررسی</button></div>`).join('')||'<div class="empty">نتیجه‌ای نیست.</div>'}}
