function ensureMusicPlayer(){if(!me)return;let box=document.getElementById('dorGlobalMusic');if(!box){box=document.createElement('div');box.id='dorGlobalMusic';box.className='dor-global-music';box.innerHTML='<audio id="dorGlobalMusicAudio" preload="auto"></audio><button id="dorMusicFab" class="dor-music-fab" type="button" aria-label="بازکردن کنترل موسیقی" title="موسیقی دستگاه من">🎶</button><div class="dor-music-panel" aria-label="کنترل موسیقی"><div class="dor-music-panel-head"><span class="dor-music-icon">♫</span><div class="dor-music-title">موسیقی دستگاه من</div><button id="dorMusicClose" type="button" aria-label="بستن">✕</button></div><div class="dor-music-controls"><button id="dorMusicEnable" type="button">▶ فعال‌کردن</button><button id="dorMusicMute" type="button" aria-label="قطع صدای من">🔊 صدای من</button></div></div>';document.body.append(box);globalMusicAudio=document.getElementById('dorGlobalMusicAudio');globalMusicAudio.addEventListener('ended',()=>{globalMusicLocalPlaying=false;updateMusicPlayer()});globalMusicAudio.addEventListener('pause',()=>{if(globalMusicAudio.ended)globalMusicLocalPlaying=false;updateMusicPlayer()});const fab=$('#dorMusicFab');const saved=(()=>{try{return JSON.parse(localStorage.getItem('dor_music_position')||'null')}catch{return null}})();const place=(x,y)=>{const maxX=Math.max(4,window.innerWidth-33),maxY=Math.max(4,window.innerHeight-33);x=Math.min(maxX,Math.max(4,x));y=Math.min(maxY,Math.max(4,y));box.style.left=x+'px';box.style.top=y+'px';box.style.right='auto';box.style.bottom='auto';try{localStorage.setItem('dor_music_position',JSON.stringify({x,y}))}catch{}};if(saved&&Number.isFinite(saved.x)&&Number.isFinite(saved.y))place(saved.x,saved.y);else place(Math.max(4,window.innerWidth-38),Math.max(4,window.innerHeight-130));fab.addEventListener('pointerdown',e=>{if(box.classList.contains('is-expanded'))return;musicDragged=false;musicFabDrag={id:e.pointerId,x:e.clientX,y:e.clientY,left:parseFloat(box.style.left)||4,top:parseFloat(box.style.top)||4};fab.setPointerCapture?.(e.pointerId)});fab.addEventListener('pointermove',e=>{if(!musicFabDrag||musicFabDrag.id!==e.pointerId)return;const dx=e.clientX-musicFabDrag.x,dy=e.clientY-musicFabDrag.y;if(Math.abs(dx)>5||Math.abs(dy)>5)musicDragged=true;if(musicDragged)place(musicFabDrag.left+dx,musicFabDrag.top+dy)});const endDrag=()=>{musicFabDrag=null};fab.addEventListener('pointerup',endDrag);fab.addEventListener('pointercancel',endDrag);fab.addEventListener('click',()=>{if(musicDragged){musicDragged=false;return}box.classList.add('is-expanded');box.style.left='12px';box.style.top='12px';box.style.right='12px';box.style.bottom='auto';updateMusicPlayer()});$('#dorMusicClose').onclick=()=>{box.classList.remove('is-expanded');const savedPos=(()=>{try{return JSON.parse(localStorage.getItem('dor_music_position')||'null')}catch{return null}})();const x=savedPos&&Number.isFinite(savedPos.x)?savedPos.x:Math.max(4,window.innerWidth-38),y=savedPos&&Number.isFinite(savedPos.y)?savedPos.y:Math.max(4,window.innerHeight-130);box.style.right='auto';place(x,y)};$('#dorMusicEnable').onclick=async()=>{if(!globalMusicState?.url){toast('فعلاً آهنگی آپلود نشده است');return}try{if(globalMusicLocalPlaying&&!globalMusicAudio.paused){globalMusicAudio.pause();globalMusicLocalPlaying=false;updateMusicPlayer();return}globalMusicMuted=false;localStorage.setItem('dor_music_muted','0');globalMusicAudio.muted=false;if(globalMusicAudio.src!==new URL(globalMusicState.url,location.origin).href){globalMusicAudio.src=globalMusicState.url;globalMusicAudio.load()}await globalMusicAudio.play();globalMusicLocalPlaying=true;updateMusicPlayer()}catch{globalMusicLocalPlaying=false;toast('پخش موسیقی ممکن نشد؛ دوباره دکمه را بزن')}};$('#dorMusicMute').onclick=()=>{globalMusicMuted=!globalMusicMuted;localStorage.setItem('dor_music_muted',globalMusicMuted?'1':'0');if(globalMusicAudio)globalMusicAudio.muted=globalMusicMuted;updateMusicPlayer()};window.addEventListener('resize',()=>{if(!box.classList.contains('is-expanded')){const x=parseFloat(box.style.left)||4,y=parseFloat(box.style.top)||4;place(x,y)}})}box.style.display='block';if(!globalMusicAudio)globalMusicAudio=$('#dorGlobalMusicAudio');fetchGlobalMusic();if(!musicStateTimer)musicStateTimer=setInterval(fetchGlobalMusic,15000)}
function updateMusicPlayer(){const box=$('#dorGlobalMusic');if(!box)return;const title=box.querySelector('.dor-music-title');if(title)title.textContent=globalMusicState?.title||'موسیقی سراسری';const mute=$('#dorMusicMute'),enable=$('#dorMusicEnable');if(mute)mute.textContent=globalMusicMuted?'🔇 صدای من قطع است':'🔊 صدای من روشن است';if(enable)enable.textContent=globalMusicLocalPlaying&&globalMusicAudio&&!globalMusicAudio.paused?'■ قطع کردن موسیقی':'▶ فعال‌کردن موسیقی';box.classList.toggle('is-playing',!!(globalMusicLocalPlaying&&globalMusicAudio&&!globalMusicAudio.paused));if(globalMusicAudio)globalMusicAudio.muted=globalMusicMuted}
async function fetchGlobalMusic(){if(!me)return;try{const d=await api('/music/state');applyGlobalMusic(d.music||{});}catch{}}
function applyGlobalMusic(st){const prev=globalMusicState;globalMusicState=st;if(!globalMusicAudio)globalMusicAudio=$('#dorGlobalMusicAudio');if(globalMusicAudio&&st.url&&(!prev||prev.url!==st.url)){const wasPlaying=globalMusicLocalPlaying;globalMusicAudio.src=st.url;globalMusicAudio.load();globalMusicLocalPlaying=false;if(wasPlaying)toast('آهنگ تغییر کرد؛ برای پخش دوباره دکمه موسیقی را بزن')}if(globalMusicAudio){globalMusicAudio.muted=globalMusicMuted}updateMusicPlayer()}
window.addEventListener('pageshow',()=>{refreshUnreadBadge();if(view==='chat'&&activeChat&&aceChatWasTyping)setTimeout(()=>{const f=$('#messageText');if(f&&document.visibilityState==='visible')f.focus({preventScroll:true})},250)});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){refreshUnreadBadge();if(view==='chat'&&activeChat&&aceChatWasTyping)setTimeout(()=>$('#messageText')?.focus({preventScroll:true}),220)}});
function showAceStartupRetry(err){app.innerHTML=`<main class="ace-intro" style="min-height:100dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:28px"><div class="ace-logo-orb">A</div><h1>اتصال به ACE CLUB برقرار نشد</h1><p>ممکن است اینترنت ضعیف باشد یا سرور دیر پاسخ بدهد. حساب و اطلاعاتت حذف نشده‌اند.</p><p class="muted small">${esc(err?.message||'اتصال را بررسی کن و دوباره تلاش کن.')}</p><button class="ace-join" id="aceStartupRetry" type="button">تلاش دوباره</button></main>`;$('#aceStartupRetry')?.addEventListener('click',()=>{const b=$('#aceStartupRetry');if(b){b.disabled=true;b.textContent='در حال اتصال…'}init()})}
async function init(){const adminUsersMatch=location.hash.match(/^#admin\/users(?:\?(.*))?$/);const adminUsersParams=adminUsersMatch?new URLSearchParams(adminUsersMatch[1]||''):null;const adminUsersPage=adminUsersParams?Math.max(1,Number(adminUsersParams.get('page'))||1):1;try{if(initialPostPath)history.replaceState({aceView:'postDetail',acePost:initialPostPath[1]},'',location.pathname);else if(adminUsersMatch){history.replaceState({aceView:'admin',adminSection:'users',adminUsersPage,adminUsersParams:adminUsersParams.toString()},'',location.href)}else if(initialHashRoute){history.replaceState({aceView:initialHashRoute.view},'',location.href)}else{history.replaceState({aceView:'home'},'','/#home');history.pushState({aceView:'home'},'','/#home')}}catch{}applyTheme(localStorage.getItem('ddtheme')||'dark');if(!localStorage.getItem('ddappbackgroundImage')&&localStorage.getItem('ddbackgroundImage'))localStorage.setItem('ddappbackgroundImage',localStorage.getItem('ddbackgroundImage'));applyAppBackground(localStorage.getItem('ddappbackground')||localStorage.getItem('ddbackground')||'default');applyChatBackground(localStorage.getItem('ddchatbackground')||'default');try{const ms=await api('/maintenance/status');if(ms.maintenance){try{const md=await api('/me');me=md.user;if(!['owner','creator'].includes(me.role))return maintenanceScreen()}catch{return maintenanceScreen()}}}catch{}try{const d=await api('/me');me=d.user;aceMeCacheAt=Date.now();viewStack=[];connectSocket();ensureMusicPlayer();if(adminUsersMatch){view='admin';try{await api('/admin/overview');await adminSection('users',adminUsersPage,false,adminUsersParams.toString())}catch{view='admin';adminScreen()}}else if(initialGroupPath){await resumeInitialGroupLink()}else if(initialHashRoute){await resumeInitialHashRoute()}else{view=initialPostPath?'postDetail':initialUserPath?'publicProfile':'home';if(initialPostPath)window.currentPostId=initialPostPath[1];if(initialUserPath)window.publicProfileId=Number(initialUserPath[1]);render()}}catch(err){me=null;if(err?.status===401||err?.status===403){if(!localStorage.getItem('ace_intro_seen'))showIntro();else authScreen()}else showAceStartupRetry(err)}}init();
document.addEventListener('click',e=>{const b=e.target.closest('[data-admin-store-open]');if(b)adminStoreScreen().catch(err=>toast(err.message));const f=e.target.closest('[data-admin-files-open]');if(f)adminFilesScreen().catch(err=>toast(err.message))});
async function adminFilesScreen(){
 shell(`${topbar('فایل‌های من')}<main class="content"><button class="btn secondary" data-view="admin">← بازگشت به پنل مدیریت</button><section class="hero"><h2>📦 مدیریت نسخه اندروید</h2><p>فقط فایل APK معتبر بارگذاری کن؛ نسخه فعال برای دانلود عمومی نمایش داده می‌شود.</p></section><section class="card"><form id="aceApkUpload" class="form-grid"><label>شماره نسخه<input class="field" name="version" required maxlength="40" placeholder="مثلاً 1.0.1"></label><label>فایل APK<input class="field" type="file" name="apk" accept=".apk,application/vnd.android.package-archive" required></label><small class="muted">حداکثر حجم ۱۵۰ مگابایت؛ فایل باید ساختار ZIP/APK داشته باشد.</small><button class="btn" type="submit">بارگذاری و فعال‌سازی نسخه</button><div id="aceApkStatus" class="muted small" role="status"></div></form></section><section class="card" id="aceApkCurrent"><h3>نسخه فعال</h3><div class="empty">در حال بارگذاری…</div></section></main>`);
 const refresh=async()=>{const host=$('#aceApkCurrent');try{const d=await api('/app-release');host.innerHTML=`<h3>نسخه فعال</h3><div class="adminrow"><div class="grow"><b>نسخه ${esc(d.version)}</b><small class="muted">${esc(d.original_name)} · ${esc(d.sizeLabel)} · ${esc(d.created_at)}</small><small class="muted">SHA-256: ${esc(d.sha256)}</small></div><a class="btn" href="${esc(d.downloadUrl)}">دانلود</a><button class="btn secondary" id="aceApkDelete" data-release-id="${d.id}">حذف</button></div>`;$('#aceApkDelete').onclick=async()=>{if(!await aceConfirm('نسخه فعال از دسترس دانلود خارج و فایل آن حذف شود؟'))return;try{await api('/admin/app-release/'+d.id,{method:'DELETE'});toast('نسخه حذف شد');refresh()}catch(e){toast(e.message)}}}catch(e){host.innerHTML=`<h3>نسخه فعال</h3><p class="muted">${esc(e.message)}</p>`}};
 $('#aceApkUpload').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,file=form.apk.files?.[0],status=$('#aceApkStatus');if(!file)return;if(!file.name.toLowerCase().endsWith('.apk')){toast('فقط فایل APK مجاز است');return}if(file.size>150*1024*1024){toast('حداکثر حجم فایل ۱۵۰ مگابایت است');return}const fd=new FormData(form),btn=form.querySelector('button[type=submit]');btn.disabled=true;status.textContent='در حال بارگذاری…';try{const r=await fetch('/api/admin/app-release',{method:'POST',body:fd,credentials:'same-origin'}),d=await r.json();if(!r.ok)throw Error(d.error||'بارگذاری ناموفق بود');status.textContent='نسخه با موفقیت فعال شد.';form.reset();toast('نسخه APK فعال شد');await refresh()}catch(err){status.textContent=err.message;toast(err.message)}finally{btn.disabled=false}};
 await refresh();
}
async function adminStoreScreen(){
 shell(`${topbar('مدیریت فروشگاه')}<main class="content"><button class="btn secondary" data-view="admin">← بازگشت به مدیریت</button><section class="hero"><h2>🛍️ مدیریت فروشگاه</h2><p>جست‌وجو با شناسه یا کد کاربری؛ فعال‌سازی اشتراک و هدیه‌دادن آیتم.</p></section><section class="card"><form id="storeAdminSearch" class="row"><input class="field grow" name="q" placeholder="شناسه یا کد کاربری" required><button class="btn">جست‌وجو</button></form></section><div id="storeAdminResult"></div></main>`);
 $('#storeAdminSearch').onsubmit=async e=>{
  e.preventDefault();const q=new FormData(e.currentTarget).get('q');const box=$('#storeAdminResult');box.innerHTML='<div class="card">در حال جست‌وجو…</div>';
  let data;try{data=await api('/admin/store/user?q='+encodeURIComponent(q))}catch(err){box.innerHTML=`<div class="card">${esc(err.message)}</div>`;return}
  const u=data.user;
  box.innerHTML=`<section class="card"><h3>${esc(u.display_name)} · @${esc(u.username)}</h3><p>شناسه: ${u.id} · 🪙 ${u.coins} · 💎 ${u.diamonds}</p><div class="grid2"><div><b>اشتراک پرو</b><small>${esc(u.pro_until||'ندارد')}</small></div><div><b>شتاب‌دهی</b><small>${esc(u.boost_until||'ندارد')}</small></div><div><b>اشتراک پیام</b><small>${esc(u.message_pass_until||'ندارد')}</small></div></div><h3>ویرایش اشتراک‌های فعلی</h3><form id="storeExpiryForm" class="form-grid"><label>پایان اشتراک پرو<input name="pro_until" type="datetime-local" value="${u.pro_until&&Number.isFinite(Date.parse(u.pro_until))?new Date(u.pro_until).toISOString().slice(0,16):''}"></label><label>پایان شتاب‌دهی<input name="boost_until" type="datetime-local" value="${u.boost_until&&Number.isFinite(Date.parse(u.boost_until))?new Date(u.boost_until).toISOString().slice(0,16):''}"></label><label>پایان اشتراک پیام<input name="message_pass_until" type="datetime-local" value="${u.message_pass_until&&Number.isFinite(Date.parse(u.message_pass_until))?new Date(u.message_pass_until).toISOString().slice(0,16):''}"></label><button class="btn">ذخیره تاریخ‌ها</button></form><h3>افزودن اشتراک یا آیتم</h3><form id="storeGrantForm" class="form-grid"><label>بخش<select name="kind"><option value="pro">اشتراک پرو</option><option value="boost">شتاب‌دهی</option><option value="message_pass">اشتراک پیام</option><option value="frame">قاب آواتار</option><option value="namecolor">نام رنگی</option><option value="badge">نشان ACE</option></select></label><label>مدت روز<input name="days" type="number" min="0" max="3650" value="30"></label><label>عملیات آیتم<select name="mode"><option value="gift">فعال‌سازی رایگان</option><option value="offer">اضافه‌کردن به فروشگاه همین کاربر</option></select></label><input type="hidden" name="itemId" value=""><div class="admin-store-picker-wrap"><b>انتخاب آیتم (با پیش‌نمایش تصویری)</b><p class="muted small">روی نمونه دلخواه بزن؛ تصویر و نام دقیق آیتم نمایش داده می‌شود.</p><div class="admin-store-picker">${data.items.map(i=>`<button type="button" class="admin-store-pick" data-pick-item="${esc(i.id)}" data-pick-kind="${esc(i.kind)}"><span class="admin-cosmetic-art kind-${esc(i.kind)}">${i.kind==='frame'?'A':i.kind==='namecolor'?`<b class="ace-name-${esc(i.css)}">ACE</b>`:`<img class="ace-badge-mark" src="/assets/ace-ui/ace-mark-${String((Number(String(i.id).split('_').pop())%20)+1).padStart(2,'0')}.svg" alt="نشان ACE">`}</span><strong>${esc(i.name)}</strong><small>${i.kind==='frame'?'قاب آواتار':i.kind==='namecolor'?'نام رنگی':'نشان ACE'}</small><small>${i.kind==='frame'?'🪙':'💎'} ${Number(i.price||0).toLocaleString('fa-IR')}</small></button>`).join('')}</div><div id="adminStorePickedLabel" class="muted small">هنوز آیتمی انتخاب نشده است.</div></div><label>یادداشت<input name="note" value="هدیه مدیریت"></label><button class="btn">ثبت هدیه / فعال‌سازی</button></form><h3>آیتم‌های مالکیت فعلی</h3><div class="admin-cosmetic-preview-grid">${data.owned.map(x=>`<article class="admin-cosmetic-preview"><div class="admin-cosmetic-art kind-${esc(x.item.kind)}"><span>${x.item.kind==='frame'?'◉':x.item.kind==='namecolor'?'Aa':'✦'}</span></div><b>${esc(x.item.name)}</b><small>${esc(x.item.kind)} · ${esc(x.owned_at)}</small></article>`).join('')||'آیتمی ندارد'}</div><h3>سوابق مدیریت</h3>${data.grants.map(g=>`<div class="userrow"><span class="grow">${esc(g.kind)} · ${esc(g.item_id)}<small>${esc(g.starts_at)} تا ${esc(g.expires_at||'دائمی')}</small></span><span>${esc(g.note||'')}</span></div>`).join('')||'<p class="muted">سابقه‌ای ثبت نشده</p>'}</section>`;
  const expiryForm=$('#storeExpiryForm');expiryForm.onsubmit=async ev=>{ev.preventDefault();const f=new FormData(expiryForm),payload={};for(const k of ['pro_until','boost_until','message_pass_until'])payload[k]=f.get(k)?new Date(f.get(k)).toISOString():null;try{await api('/admin/store/user/'+u.id,{method:'PATCH',body:payload});toast('تاریخ اشتراک‌ها ذخیره شد');$('#storeAdminSearch').requestSubmit()}catch(err){toast(err.message)}};const form=$('#storeGrantForm');form.querySelectorAll('[data-pick-item]').forEach(card=>card.onclick=()=>{const kind=form.querySelector('[name=kind]').value;if(!['frame','namecolor','badge'].includes(kind)){toast('ابتدا یکی از سه بخش قاب، نام رنگی یا نشان ACE را انتخاب کن');return}if(card.dataset.pickKind!==kind){toast('این آیتم مربوط به بخش دیگری است');return}form.querySelector('[name=itemId]').value=card.dataset.pickItem;form.querySelectorAll('[data-pick-item]').forEach(x=>x.classList.toggle('selected',x===card));const label=$('#adminStorePickedLabel');if(label)label.textContent='انتخاب‌شده: '+card.querySelector('strong').textContent});form.querySelector('[name=kind]').onchange=()=>{const k=form.querySelector('[name=kind]').value;form.querySelector('[name=itemId]').value='';form.querySelectorAll('[data-pick-item]').forEach(x=>x.classList.remove('selected'));const label=$('#adminStorePickedLabel');if(label)label.textContent='یک آیتم از بخش '+({frame:'قاب آواتار',namecolor:'نام رنگی',badge:'نشان ACE'}[k]||'اشتراک')+' انتخاب کن';};
  form.onsubmit=async ev=>{ev.preventDefault();const f=new FormData(form),kind=f.get('kind');try{await api('/admin/store/grant',{method:'POST',body:{userId:u.id,kind,itemId:f.get('itemId'),mode:f.get('mode'),days:Number(f.get('days')),note:f.get('note')}});toast('تغییرات فروشگاه ثبت شد');$('#storeAdminSearch').requestSubmit()}catch(err){toast(err.message)}};
 };
}
